const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:34,740", "arabic": "وَأَظُنُّ أَنَّ الْأَمْرَ لَمْ يَحِنْ أَجَلُهُ؟ لَمْ يَحِنْ أَجَلُهُ؟", "segs": null, "full_uz": "Nazarimda, bu ishning vaqti hali kelmagan, deysanmi? Vaqti kelmaganmi?", "note": null},
  {"num": 4, "time": "00:00:34,740 --> 00:00:43,299", "arabic": "وَمَتَى تَظُنُّ أَنَّ الْأَوَانَ قَدْ آنَ؟ عِنْدَمَا يَخُزُّ الشَّيْبُ رَأْسَكَ؟ أَمْ عِنْدَمَا تَتَوَكَّأُ عَلَى عَصَاكَ؟", "segs": [{"ar": "وَمَتَى تَظُنُّ أَنَّ الْأَوَانَ قَدْ آنَ؟", "uz": "Vaqti qachon kelgan bo'ladi deb o'ylaysan?"}, {"ar": "عِنْدَمَا يَخُزُّ الشَّيْبُ رَأْسَكَ؟", "uz": "Boshingga oqarish tushganidami?"}, {"ar": "أَمْ عِنْدَمَا تَتَوَكَّأُ عَلَى عَصَاكَ؟", "uz": "Yoki tayoqqa suyanadigan bo'lganingdami?"}], "full_uz": "Vaqti qachon kelgan bo'ladi deb o'ylaysan? Boshingga oqarish tushganidami? Yoki tayoqqa suyanadigan bo'lganingdami?", "note": null},
  {"num": 7, "time": "00:00:43,299 --> 00:00:52,100", "arabic": "يَا أُمِّي يَا أُمَّ أَحْمَدَ، أَرْجُوكِ أَنْ تَرَيْ الْأَمْرَ كَمَا أَرَاهُ، أَوْ تُدْرِكِينَ مَعْنَى زَوَاجِي، زَوَاجِي الْآنَ سَيُغَيِّرُ حَيَاتِي كُلَّهَا", "segs": [{"ar": "يَا أُمِّي يَا أُمَّ أَحْمَدَ، أَرْجُوكِ أَنْ تَرَيْ الْأَمْرَ كَمَا أَرَاهُ", "uz": "Onajon, ey Ahmadning onasi, iltimos, bu ishga men ko'rgandek qara"}, {"ar": "أَوْ تُدْرِكِينَ مَعْنَى زَوَاجِي", "uz": "yoki mening uylanishimning ma'nosini tushunasan"}, {"ar": "زَوَاجِي الْآنَ سَيُغَيِّرُ حَيَاتِي كُلَّهَا", "uz": "Hozir uylanishim butun hayotimni o'zgartirib yuboradi"}], "full_uz": "Onajon, ey Ahmadning onasi, iltimos, bu ishga men ko'rgandek qara — yoki mening uylanishimning ma'nosini tushunasan. Hozir uylanishim butun hayotimni o'zgartirib yuboradi.", "note": null},
  {"num": 11, "time": "00:00:52,100 --> 00:01:01,319", "arabic": "وَمَنْ سَأَتَزَوَّجُهَا إِنْ رَضِيَتْ أَنْ تَعِيشَ كَمَا نَعِيشُ، فَلِمَ تَرْضَى أَنْ تَعِيشَ فِي ظِلِّ رَجُلٍ تَرَاهُ فِي السَّنَةِ وَالسَّنَتَيْنِ مَرَّةً أَوْ مَرَّتَيْنِ", "segs": [{"ar": "وَمَنْ سَأَتَزَوَّجُهَا إِنْ رَضِيَتْ أَنْ تَعِيشَ كَمَا نَعِيشُ", "uz": "Uylanadigan qizim, agar biz yashagandek yashashga rozi bo'lsa ham"}, {"ar": "فَلِمَ تَرْضَى أَنْ تَعِيشَ فِي ظِلِّ رَجُلٍ", "uz": "erining soyasida yashashga nega rozi bo'lsin"}, {"ar": "تَرَاهُ فِي السَّنَةِ وَالسَّنَتَيْنِ مَرَّةً أَوْ مَرَّتَيْنِ", "uz": "bir yoki ikki yilda bir-ikki marta ko'radigan"}], "full_uz": "Uylanadigan qizim, agar biz yashagandek yashashga rozi bo'lsa ham — bir yoki ikki yilda bir-ikki marta ko'radigan erining soyasida yashashga nega rozi bo'lsin?", "note": null},
  {"num": 15, "time": "00:01:01,319 --> 00:01:07,819", "arabic": "فَإِمَّا أَنْ أَتْرُكَ مَا نَذَرْتُ عُمُرِي لِأَجْلِهِ وَأَجْلِسَ فِي جِوَارِهَا، وَإِمَّا أَنْ أُؤَجِّلَ الْأَمْرَ قَلِيلًا", "segs": [{"ar": "فَإِمَّا أَنْ أَتْرُكَ مَا نَذَرْتُ عُمُرِي لِأَجْلِهِ وَأَجْلِسَ فِي جِوَارِهَا", "uz": "Yo umrimni bag'ishlagan narsamni tashlab, uning yonida o'tirishim kerak"}, {"ar": "وَإِمَّا أَنْ أُؤَجِّلَ الْأَمْرَ قَلِيلًا", "uz": "yoki bu ishni bir oz kechiktirishim kerak"}], "full_uz": "Yo umrimni bag'ishlagan narsamni tashlab, uning yonida o'tirishim, yoki bu ishni bir oz kechiktirishim kerak.", "note": null},
  {"num": 18, "time": "00:01:07,819 --> 00:01:12,420", "arabic": "فَمَا يَضِيرُكَ لَوْ أَجَّلْنَاهُ قَلِيلًا؟ مَا يَضِيرُنِي؟", "segs": null, "full_uz": "Bir oz kechiktirsak senga nima zarar? Menga nima zarar?", "note": null},
  {"num": 20, "time": "00:01:12,420 --> 00:01:19,159", "arabic": "يَضِيرُنِي أَنَّنِي أُرِيدُ أَنْ أُزَوِّجَكَ كَيْ أَرَى أَطْفَالَكَ، أَمْ تَبْخَلُ عَلَيَّ بِهَذَا أَيْضًا؟", "segs": [{"ar": "يَضِيرُنِي أَنَّنِي أُرِيدُ أَنْ أُزَوِّجَكَ كَيْ أَرَى أَطْفَالَكَ", "uz": "Menga zarari — seni uylantirib, farzandlaringni ko'rishni istayman"}, {"ar": "أَمْ تَبْخَلُ عَلَيَّ بِهَذَا أَيْضًا؟", "uz": "Yoki bundan ham meni mahrum qilasanmi?"}], "full_uz": "Menga zarari — seni uylantirib, farzandlaringni ko'rishni istayman. Yoki bundan ham meni mahrum qilasanmi?", "note": null},
  {"num": 22, "time": "00:01:19,819 --> 00:01:26,420", "arabic": "أَلَيْسَ مِنْ حَقِّي كَأُمٍّ أَنْ أَرَى أَطْفَالَكَ قَبْلَ أَنْ يُعَاجِلَنِي مَا لَا بُدَّ مِنْهُ؟", "segs": [{"ar": "أَلَيْسَ مِنْ حَقِّي كَأُمٍّ أَنْ أَرَى أَطْفَالَكَ", "uz": "Ona sifatida farzandlaringni ko'rishga haqqim yo'qmi"}, {"ar": "قَبْلَ أَنْ يُعَاجِلَنِي مَا لَا بُدَّ مِنْهُ؟", "uz": "muqarrar bo'lgan narsa meni oldindan tutib olmasidan burun"}], "full_uz": "Ona sifatida, muqarrar bo'lgan narsa meni oldindan tutib olmasidan burun farzandlaringni ko'rishga haqqim yo'qmi?", "note": null},
  {"num": 24, "time": "00:01:26,420 --> 00:01:33,719", "arabic": "أَطَالَ اللَّهُ عُمْرَكِ يَا أُمَّهْ وَأَبْقَاكِ، أَعْمَارُنَا بِيَدِ خَالِقِنَا، كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ", "segs": [{"ar": "أَطَالَ اللَّهُ عُمْرَكِ يَا أُمَّهْ وَأَبْقَاكِ", "uz": "Alloh umringizni uzun qilsin, onajon, sizni saqlasin"}, {"ar": "أَعْمَارُنَا بِيَدِ خَالِقِنَا", "uz": "umrlarimiz Yaratganimiz qo'lida"}, {"ar": "كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ", "uz": "har bir jon o'limni totuvchidir"}], "full_uz": "Alloh umringizni uzun qilsin, onajon, sizni saqlasin — umrlarimiz Yaratganimiz qo'lida, har bir jon o'limni totuvchidir.", "note": "«كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ» — Оли Imron surasi 185-oyatidan mashhur ibora."},
  {"num": 27, "time": "00:01:33,719 --> 00:01:39,799", "arabic": "أَلَا يَكْفِينِي أَنَّنِي أَعِيشُ السِّنِينَ وَأَنَا مَحْرُومَةٌ مِنْكَ", "segs": null, "full_uz": "Yillar bo'yi sendan mahrum bo'lib yashaganim yetmaydimi?", "note": null},
  {"num": 28, "time": "00:01:39,799 --> 00:01:52,719", "arabic": "وَأَنْتَ تَرْتَحِلُ مِنَ الشَّرْقِ إِلَى الْغَرْبِ، أَتُرِيدُ أَنْ تَحْرِمَنِي مِنْ رُؤْيَةِ أَطْفَالِكَ أَيْضًا؟ فَإِنَّكَ لَا تَخْشَى أَنْ تَسْتَأْثِرَ بِكَ امْرَأَةٌ دُونِي، أَوْ يَشْغَلَنِي عَنْكَ الْأَطْفَالُ إِنْ كَتَبَ اللَّهُ لِي ذُرِّيَّةً", "segs": [{"ar": "وَأَنْتَ تَرْتَحِلُ مِنَ الشَّرْقِ إِلَى الْغَرْبِ", "uz": "Sen sharqdan g'arbga sayohat qilib yurasan"}, {"ar": "أَتُرِيدُ أَنْ تَحْرِمَنِي مِنْ رُؤْيَةِ أَطْفَالِكَ أَيْضًا؟", "uz": "endi farzandlaringni ko'rishdan ham meni mahrum qilmoqchimisan?"}, {"ar": "فَإِنَّكَ لَا تَخْشَى أَنْ تَسْتَأْثِرَ بِكَ امْرَأَةٌ دُونِي", "uz": "Sen boshqa bir ayolning seni butunlay o'ziga tortib qo'yishidan qo'rqmaysan"}, {"ar": "أَوْ يَشْغَلَنِي عَنْكَ الْأَطْفَالُ إِنْ كَتَبَ اللَّهُ لِي ذُرِّيَّةً", "uz": "yoki Alloh menga zurriyot yozsa, bolalar meni sendan chalg'itishidan"}], "full_uz": "Sen sharqdan g'arbga sayohat qilib yurasan-yu, endi farzandlaringni ko'rishdan ham meni mahrum qilmoqchimisan? Sen esa boshqa bir ayolning seni butunlay o'ziga tortib qo'yishidan qo'rqmaysan — yoki Alloh menga zurriyot yozsa, bolalar meni sendan chalg'itishidan.", "note": null},
  {"num": 32, "time": "00:01:52,719 --> 00:01:59,339", "arabic": "اِبْنَ حَنْبَلٍ، أَنَا أَعْلَمُ أَنَّ الدُّنْيَا بِأَسْرِهَا لَنْ تَشْغَلَكَ عَنِّي", "segs": null, "full_uz": "Ibn Hanbal, men bilamanki, butun dunyo ham seni mendan chalg'itolmaydi.", "note": null},
  {"num": 34, "time": "00:01:59,339 --> 00:02:08,539", "arabic": "أَلَا لَيْتَنِي أَرَى أَطْفَالَكَ، أَضَعُهُمْ فِي حِجْرِي، وَأَرَاهُمْ مِنْ حَوْلِي يَلْعَبُونَ", "segs": [{"ar": "أَلَا لَيْتَنِي أَرَى أَطْفَالَكَ", "uz": "Koshki farzandlaringni ko'rsam"}, {"ar": "أَضَعُهُمْ فِي حِجْرِي", "uz": "ularni quchog'imga qo'ysam"}, {"ar": "وَأَرَاهُمْ مِنْ حَوْلِي يَلْعَبُونَ", "uz": "va atrofimda o'ynayotganlarini ko'rsam"}], "full_uz": "Koshki farzandlaringni ko'rsam, ularni quchog'imga qo'ysam va atrofimda o'ynayotganlarini ko'rsam.", "note": null},
  {"num": 37, "time": "00:02:23,879 --> 00:02:51,879", "arabic": "أَحْمَدُ لَا يُرْغَمُ عَلَى الزَّوَاجِ يَا أُمَّ خَالِدٍ، فَهُوَ ابْنُ حَنْبَلٍ الَّذِي تَحْتَرِمُهُ أَكَابِرُ بَغْدَادَ، فَكَيْفَ تُرِيدِينَ مِنِّي أَنْ أُجْبِرَهُ عَلَى مَا يَكْرَهُ؟", "segs": [{"ar": "أَحْمَدُ لَا يُرْغَمُ عَلَى الزَّوَاجِ يَا أُمَّ خَالِدٍ", "uz": "Ahmad nikohga majbur qilinmaydi, ey Xolidning onasi"}, {"ar": "فَهُوَ ابْنُ حَنْبَلٍ الَّذِي تَحْتَرِمُهُ أَكَابِرُ بَغْدَادَ", "uz": "u Bag'dodning kattalari hurmat qiladigan Ibn Hanbal-ku"}, {"ar": "فَكَيْفَ تُرِيدِينَ مِنِّي أَنْ أُجْبِرَهُ عَلَى مَا يَكْرَهُ؟", "uz": "undan qanday qilib yoqmagan narsaga uni majburlashimni istaysan?"}], "full_uz": "Ahmad nikohga majbur qilinmaydi, ey Xolidning onasi — u Bag'dodning kattalari hurmat qiladigan Ibn Hanbal-ku. Undan qanday qilib yoqmagan narsaga uni majburlashimni istaysan?", "note": null},
  {"num": 41, "time": "00:02:51,879 --> 00:02:58,840", "arabic": "أَنْتَ أُمُّهُ وَمِنْ حَقِّكِ عَلَيْهِ الطَّاعَةُ، أَجَلْ أَعْرِفُ ذَلِكَ", "segs": null, "full_uz": "Sen uning onasisan, itoat qilish senga uning ustidagi haqqingdir. Ha, buni bilaman.", "note": null},
  {"num": 43, "time": "00:02:58,840 --> 00:03:10,099", "arabic": "وَأَحْمَدُ يَعْرِفُ حُقُوقِي جَيِّدًا، وَلَوْ طَلَبْتُ مِنْهُ الزَّوَاجَ لَتَزَوَّجَ مِنَ الْغَدِ، وَلَكِنِّي لَا أُرِيدُ ذَلِكَ، أُرِيدُهُ أَنْ يَكُونَ رَاغِبًا", "segs": [{"ar": "وَأَحْمَدُ يَعْرِفُ حُقُوقِي جَيِّدًا", "uz": "Ahmad mening huquqlarimni yaxshi biladi"}, {"ar": "وَلَوْ طَلَبْتُ مِنْهُ الزَّوَاجَ لَتَزَوَّجَ مِنَ الْغَدِ", "uz": "agar undan nikohni so'rasam, ertagayoq uylanadi"}, {"ar": "وَلَكِنِّي لَا أُرِيدُ ذَلِكَ، أُرِيدُهُ أَنْ يَكُونَ رَاغِبًا", "uz": "ammo men buni xohlamayman, uning o'zi xohlashini istayman"}], "full_uz": "Ahmad mening huquqlarimni yaxshi biladi — agar undan nikohni so'rasam, ertagayoq uylanadi. Ammo men buni xohlamayman, uning o'zi xohlashini istayman.", "note": null},
  {"num": 46, "time": "00:03:10,099 --> 00:03:17,060", "arabic": "فَإِذَا كَانَ الْإِسْلَامُ يَمْنَعُنَا أَنْ نُجْبِرَ بَنَاتِنَا، فَكَيْفَ لِي أَنْ أُرْغِمَ رَجُلًا مِثْلَ أَحْمَدَ؟", "segs": null, "full_uz": "Islom bizga qizlarimizni majburlashni man qilgan bo'lsa, Ahmadga o'xshagan bir kishini qanday majburlay olaman?", "note": null},
  {"num": 48, "time": "00:03:17,979 --> 00:03:36,800", "arabic": "مَا الْحَلُّ إِذَنْ؟ لَعَلَّ اللَّهَ يَشْرَحُ لِذَلِكَ قَلْبَهُ، أَوْ لَعَلَّهُ يُفَكِّرُ فِيمَا قُلْتُ، أَوْ لَعَلَّهُ يَقْتَنِعُ حِينَ يَرَى أَصْحَابَهُ آبَاءً تَجْرِي مِنْ حَوْلِهِمُ الْأَبْنَاءُ", "segs": [{"ar": "مَا الْحَلُّ إِذَنْ؟", "uz": "Yechim nima bo'ladi unda?"}, {"ar": "لَعَلَّ اللَّهَ يَشْرَحُ لِذَلِكَ قَلْبَهُ", "uz": "Balki Alloh uning qalbini shu ishga kenglashtirib qo'yar"}, {"ar": "أَوْ لَعَلَّهُ يُفَكِّرُ فِيمَا قُلْتُ", "uz": "yoki aytganlarim haqida o'ylab ko'rar"}, {"ar": "أَوْ لَعَلَّهُ يَقْتَنِعُ حِينَ يَرَى أَصْحَابَهُ آبَاءً تَجْرِي مِنْ حَوْلِهِمُ الْأَبْنَاءُ", "uz": "yoki do'stlarining otalar bo'lib, atroflarida bolalari yugurib yurganini ko'rganida ko'ngli tinchir"}], "full_uz": "Yechim nima bo'ladi unda? Balki Alloh uning qalbini shu ishga kenglashtirib qo'yar, yoki aytganlarim haqida o'ylab ko'rar, yoki do'stlarining otalar bo'lib, atroflarida bolalari yugurib yurganini ko'rganida ko'ngli tinchir.", "note": null},
  {"num": 52, "time": "00:03:36,800 --> 00:03:45,800", "arabic": "أَتَرَاهُ يَخْشَى أَلَّا تَرْضَى فَتَاةٌ بِارْتِحَالِهِ وَسَفَرِهِ أَمْ أَنَّ هُنَاكَ سَبَبًا آخَرَ؟ مِثْلَ مَاذَا؟", "segs": [{"ar": "أَتَرَاهُ يَخْشَى أَلَّا تَرْضَى فَتَاةٌ بِارْتِحَالِهِ وَسَفَرِهِ", "uz": "Sizga qolsa, bir qiz uning safar-safarga chiqishiga rozi bo'lmasligidan qo'rqayotgandirmi"}, {"ar": "أَمْ أَنَّ هُنَاكَ سَبَبًا آخَرَ؟", "uz": "yoki boshqa sabab bordir?"}, {"ar": "مِثْلَ مَاذَا؟", "uz": "Masalan qanaqa?"}], "full_uz": "Sizga qolsa, bir qiz uning safar-safarga chiqishiga rozi bo'lmasligidan qo'rqayotgandirmi, yoki boshqa sabab bordir? Masalan qanaqa?", "note": null},
  {"num": 54, "time": "00:03:45,800 --> 00:03:52,560", "arabic": "أَلَيْسَ مِنَ الْمُمْكِنِ أَنَّهُ يَتَجَنَّبُ الزَّوَاجَ مِنْ أَجْلِكِ أَنْتِ لَا مِنْ أَجْلِ نَفْسِهِ؟", "segs": null, "full_uz": "U nikohdan o'zi uchun emas, siz uchun qochib yurgandir, mumkin emasmi?", "note": null},
  {"num": 56, "time": "00:04:00,560 --> 00:04:08,860", "arabic": "لَا تَعْرِفُ يَا ابْنَ حَنْبَلٍ، أَنَا أَرَى خَالَتِي أُمَّ أَحْمَدَ مُحِقَّةً فِيمَا تَطْلُبُ، وَأَرَاكَ لَسْتَ عَلَى حَقٍّ فِيمَا تَرْفُضُ", "segs": [{"ar": "لَا تَعْرِفُ يَا ابْنَ حَنْبَلٍ", "uz": "Bilmaysan, Ibn Hanbal"}, {"ar": "أَنَا أَرَى خَالَتِي أُمَّ أَحْمَدَ مُحِقَّةً فِيمَا تَطْلُبُ", "uz": "men xolam Ummu Ahmadni talab qilgan narsasida haqli deb bilaman"}, {"ar": "وَأَرَاكَ لَسْتَ عَلَى حَقٍّ فِيمَا تَرْفُضُ", "uz": "seni esa rad etganingda haq emas deb bilaman"}], "full_uz": "Bilmaysan, Ibn Hanbal — men xolam Ummu Ahmadni talab qilgan narsasida haqli deb bilaman, seni esa rad etganingda haq emas deb bilaman.", "note": null},
  {"num": 59, "time": "00:04:08,860 --> 00:04:22,959", "arabic": "أَعْرِفُ ذَلِكَ يَا ابْنَ نُوحٍ، وَلَكِنَّ الْحَقَّ أَنَّ نَفْسِي قَدْ لَا تَحْتَمِلُ أَنْ تَأْتِيَ امْرَأَةٌ إِلَى الْبَيْتِ وَتَسْلُبَ مِنِّي الْوَقْتَ الَّذِي أَمْنَحُهُ إِلَى رِعَايَةِ أُمِّي، وَكَمَا تَعْلَمُ هُوَ قَلِيلٌ", "segs": [{"ar": "أَعْرِفُ ذَلِكَ يَا ابْنَ نُوحٍ", "uz": "Buni bilaman, Ibn Nuh"}, {"ar": "وَلَكِنَّ الْحَقَّ أَنَّ نَفْسِي قَدْ لَا تَحْتَمِلُ أَنْ تَأْتِيَ امْرَأَةٌ إِلَى الْبَيْتِ", "uz": "lekin haqiqat shuki, bir ayolning uyga kelishiga jonim chidamasligi mumkin"}, {"ar": "وَتَسْلُبَ مِنِّي الْوَقْتَ الَّذِي أَمْنَحُهُ إِلَى رِعَايَةِ أُمِّي", "uz": "va onamga g'amxo'rlik qilishga bag'ishlagan vaqtimni tortib olishiga"}, {"ar": "وَكَمَا تَعْلَمُ هُوَ قَلِيلٌ", "uz": "u ham bilasan — oz"}], "full_uz": "Buni bilaman, Ibn Nuh, lekin haqiqat shuki — bir ayolning uyga kelib, onamga g'amxo'rlik qilishga bag'ishlagan vaqtimni tortib olishiga jonim chidamasligi mumkin, u ham bilasan — oz.", "note": null},
  {"num": 63, "time": "00:04:22,959 --> 00:04:33,500", "arabic": "وَأَنْتَ تَعْلَمُ أَيْضًا أَنِّي آلَيْتُ عَلَى نَفْسِي أَنْ لَا أَكُفَّ عَنْ طَلَبِ حَدِيثِ رَسُولِ اللَّهِ حَتَّى لَا يَبْقَى عَالِمٌ أَوْ شَيْخٌ يُعْتَدُّ بِقَوْلِهِ إِلَّا وَقَصَدْتُهُ", "segs": [{"ar": "وَأَنْتَ تَعْلَمُ أَيْضًا أَنِّي آلَيْتُ عَلَى نَفْسِي أَنْ لَا أَكُفَّ عَنْ طَلَبِ حَدِيثِ رَسُولِ اللَّهِ", "uz": "Yana bilasan — men o'zimga qasam ichganman, Rasululloh hadisini izlashdan to'xtamaslikka"}, {"ar": "حَتَّى لَا يَبْقَى عَالِمٌ أَوْ شَيْخٌ يُعْتَدُّ بِقَوْلِهِ إِلَّا وَقَصَدْتُهُ", "uz": "toki e'tibor beriladigan biror olim yoki shayx qolmasin, faqat unga bormaguncha"}], "full_uz": "Yana bilasan — men o'zimga qasam ichganman, Rasululloh hadisini izlashdan to'xtamaslikka, toki e'tibor beriladigan biror olim yoki shayx qolmasin, faqat unga bormaguncha.", "note": null},
  {"num": 66, "time": "00:04:33,500 --> 00:04:39,500", "arabic": "وَمَا أَكْفَرَهُمْ! حَالُكَ حَالُكَ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Ular qanchalik kofir! Sening holing — o'z holing, Ibn Hanbal.", "note": null},
  {"num": 68, "time": "00:04:39,500 --> 00:04:43,779", "arabic": "أَنَا سَيِّدٌ، لَا يَا ابْنَ نُوحٍ حَالُكُمْ لَيْسَ كَحَالِي", "segs": null, "full_uz": "Men sayyidman. Yo'q, Ibn Nuh, sizning holingiz mening holimga o'xshamaydi.", "note": null},
  {"num": 70, "time": "00:04:43,779 --> 00:04:54,339", "arabic": "إِنَّ أَهْلَكَ لَيْسُوا بِحَاجَةٍ مَاسَّةٍ إِلَيَّ، أَمَّا زَوْجُكَ وَعِيَالُكَ فَكَمْ مِنْ مَرَّةٍ شُغِلَتْ بِهِمْ عَنْ سَفَرِكَ وَتَرْحَالِكَ؟ أَتُنْكِرُ ذَلِكَ؟", "segs": [{"ar": "إِنَّ أَهْلَكَ لَيْسُوا بِحَاجَةٍ مَاسَّةٍ إِلَيَّ", "uz": "Sening oilangda menga qattiq muhtoj kishi yo'q"}, {"ar": "أَمَّا زَوْجُكَ وَعِيَالُكَ فَكَمْ مِنْ مَرَّةٍ شُغِلَتْ بِهِمْ عَنْ سَفَرِكَ وَتَرْحَالِكَ؟", "uz": "xotining va bolalaring esa necha marta seni safar-safaringdan chalg'itgan?"}, {"ar": "أَتُنْكِرُ ذَلِكَ؟", "uz": "Buni inkor etasanmi?"}], "full_uz": "Sening oilangda menga qattiq muhtoj kishi yo'q — xotining va bolalaring esa necha marta seni safar-safaringdan chalg'itgan? Buni inkor etasanmi?", "note": null},
  {"num": 73, "time": "00:04:54,879 --> 00:04:57,779", "arabic": "لَا، إِذَنْ، صَدَقْتَ", "segs": null, "full_uz": "Yo'q. Unda... to'g'ri aytding.", "note": null},
  {"num": 76, "time": "00:04:57,779 --> 00:05:14,099", "arabic": "أَثْقَلُ الْآمَالِ فِي الْمِيزَانِ أَثْقَلُهَا عَلَى الْأَبْدَانِ، وَمَنْ وَفَّى الْعَمَلَ وُفِّيَ لَهُ الْأَجْرُ", "segs": [{"ar": "أَثْقَلُ الْآمَالِ فِي الْمِيزَانِ أَثْقَلُهَا عَلَى الْأَبْدَانِ", "uz": "Tarozida eng og'ir umidlar — badanlarga eng og'ir bo'lganlaridir"}, {"ar": "وَمَنْ وَفَّى الْعَمَلَ وُفِّيَ لَهُ الْأَجْرُ", "uz": "Kim amalni to'liq bajarsa, ajri ham to'liq beriladi"}], "full_uz": "Tarozida eng og'ir umidlar — badanlarga eng og'ir bo'lganlaridir. Kim amalni to'liq bajarsa, ajri ham to'liq beriladi.", "note": null},
  {"num": 78, "time": "00:05:14,099 --> 00:05:29,579", "arabic": "وَمَنْ لَمْ يَعْمَلْ رَحَلَ مِنَ الدُّنْيَا إِلَى الْآخِرَةِ بِلَا قَلِيلٍ وَلَا كَثِيرٍ، وَمَا يَنْبَغِي لِمَنْ ذَلَّ لِلَّهِ فِي طَاعَتِهِ أَنْ يَذِلَّ لِغَيْرِ اللَّهِ فِي مَجَاعَتِهِ", "segs": [{"ar": "وَمَنْ لَمْ يَعْمَلْ رَحَلَ مِنَ الدُّنْيَا إِلَى الْآخِرَةِ بِلَا قَلِيلٍ وَلَا كَثِيرٍ", "uz": "Kim amal qilmasa, dunyodan oxiratga oz ham, ko'p ham olmasdan ko'chib ketadi"}, {"ar": "وَمَا يَنْبَغِي لِمَنْ ذَلَّ لِلَّهِ فِي طَاعَتِهِ", "uz": "Allohga itoatda kamtar bo'lgan kishiga"}, {"ar": "أَنْ يَذِلَّ لِغَيْرِ اللَّهِ فِي مَجَاعَتِهِ", "uz": "o'z ochligida Allohdan boshqasi oldida kamsitilishi yarashmaydi"}], "full_uz": "Kim amal qilmasa, dunyodan oxiratga oz ham, ko'p ham olmasdan ko'chib ketadi. Allohga itoatda kamtar bo'lgan kishiga, o'z ochligida Allohdan boshqasi oldida kamsitilishi yarashmaydi.", "note": null},
  {"num": 80, "time": "00:05:29,579 --> 00:05:39,219", "arabic": "فَكَيْفَ بِمَنْ هُوَ يَتَقَلَّبُ فِي نَعِيمِ اللَّهِ وَكِفَايَتِهِ؟ يَا مُغِيثُ يَا مُغِيثُ أَغِثْنَا يَا اللَّهُ", "segs": [{"ar": "فَكَيْفَ بِمَنْ هُوَ يَتَقَلَّبُ فِي نَعِيمِ اللَّهِ وَكِفَايَتِهِ؟", "uz": "Allohning ne'mati va yetarliligida yashab yurgan kishi haqida-chi?"}, {"ar": "يَا مُغِيثُ يَا مُغِيثُ أَغِثْنَا يَا اللَّهُ", "uz": "Ey Mug'is, ey Mug'is, bizga madad ber, ey Alloh!"}], "full_uz": "Allohning ne'mati va yetarliligida yashab yurgan kishi haqida-chi? Ey Mug'is, ey Mug'is, bizga madad ber, ey Alloh!", "note": "يَا مُغِيثُ — Allohning \"Madadkor\" ma'nosidagi sifatlaridan biriga murojaat."},
  {"num": 82, "time": "00:05:39,220 --> 00:05:57,100", "arabic": "يَبْدُو أَنَّ الْأَجَلَ قَدِ اقْتَرَبَ، وَأَنَّ السَّاعَةَ قَدْ حَانَتْ", "segs": null, "full_uz": "Ajal yaqinlashganga o'xshaydi va soat kelib qolganga.", "note": null},
  {"num": 84, "time": "00:05:57,100 --> 00:06:01,660", "arabic": "أَرْجُوكَ لَا تَقُلْ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Iltimos, buni aytmang, xo'jayinim.", "note": null},
  {"num": 85, "time": "00:06:01,660 --> 00:06:16,900", "arabic": "أَأَمُوتُ حَقًّا يَا أَبَا هَاشِمٍ؟ وَلَا مَفَرَّ مِنْهُ", "segs": null, "full_uz": "Rostdan ham o'lamanmi, Abu Hoshim? Undan qochib qutulib bo'lmaydi.", "note": null},
  {"num": 87, "time": "00:06:24,900 --> 00:06:36,899", "arabic": "يَبْدُو، يَبْدُو أَنَّنِي لَنْ أَرَى بَغْدَادَ مَرَّةً أُخْرَى", "segs": null, "full_uz": "Ko'rinishidan, ko'rinishidan, Bag'dodni endi bir umr ko'rmayman.", "note": null},
  {"num": 90, "time": "00:06:36,899 --> 00:06:39,579", "arabic": "صَدَّرَكَ نَفْسِي يَا مَوْلَايَ", "segs": null, "full_uz": "Jonim sizga fido bo'lsin, xo'jayinim.", "note": null},
  {"num": 91, "time": "00:06:39,579 --> 00:07:30,879", "arabic": "لَقَدْ آنَ لِلْمُسَافِرِ أَنْ يَضَعَ عَصَاهُ", "segs": null, "full_uz": "Musofir uchun tayog'ini qo'yish vaqti keldi.", "note": "اَلْمُسَافِرُ يَضَعُ عَصَاهُ — safarning tugashi, oxirgi manzilga yetish ma'nosidagi majoziy ibora."},
  {"num": 94, "time": "00:07:30,899 --> 00:09:20,899", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى أَمْرِهِ وَقَضَائِهِ، إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Allohning amri va qazosiga hamd bo'lsin — albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": "«إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ» — Baqara surasi, 2:156-oyat."},
  {"num": 99, "time": "00:09:20,899 --> 00:09:26,379", "arabic": "رَحِمَكَ اللَّهُ يَا هَارُونُ وَاجْعَلْ مَثْوَاكَ الْجَنَّةَ", "segs": null, "full_uz": "Alloh senga rahmat qilsin, Horun, va jannatni maskaning qilsin.", "note": null},
  {"num": 101, "time": "00:09:26,379 --> 00:09:40,840", "arabic": "يَبْدُو أَنَّ الْخَبَرَ صَحِيحٌ، كُلُّ مَنْ عَلَيْهَا فَانٍ", "segs": null, "full_uz": "Xabar to'g'riga o'xshaydi. Uning ustidagi hamma faniydir.", "note": "«كُلُّ مَنْ عَلَيْهَا فَانٍ» — Rahmon surasi, 55:26-oyat."},
  {"num": 103, "time": "00:09:40,840 --> 00:09:54,040", "arabic": "رَحِمَ اللَّهُ الرَّشِيدَ وَغَفَرَ لَهُ، رَحِمَ اللَّهُ مَنْ حَجَّ عَامًا وَغَزَا عَامًا، قَامَ بِحَقِّ الْخِلَافَةِ كُلَّ وُسْعِهِ، فَتَتَبَّعَ الزَّنَادِقَةَ وَضَيَّقَ عَلَى الْمُبْتَدِعَةِ وَوَقَى الْمُسْلِمِينَ شُرُورَهُمْ", "segs": [{"ar": "رَحِمَ اللَّهُ الرَّشِيدَ وَغَفَرَ لَهُ", "uz": "Alloh ar-Rashidga rahmat qilib, uni mag'firat qilsin"}, {"ar": "رَحِمَ اللَّهُ مَنْ حَجَّ عَامًا وَغَزَا عَامًا", "uz": "Alloh bir yili haj qilib, bir yili g'azot qilgan kishiga rahmat qilsin"}, {"ar": "قَامَ بِحَقِّ الْخِلَافَةِ كُلَّ وُسْعِهِ", "uz": "U xalifalik haqini bor kuchi bilan ado etdi"}, {"ar": "فَتَتَبَّعَ الزَّنَادِقَةَ وَضَيَّقَ عَلَى الْمُبْتَدِعَةِ وَوَقَى الْمُسْلِمِينَ شُرُورَهُمْ", "uz": "zindiqlarni ta'qib qilib, bid'atchilarga tor keldi va musulmonlarni ularning yovuzligidan asradi"}], "full_uz": "Alloh ar-Rashidga rahmat qilib, uni mag'firat qilsin — Alloh bir yili haj qilib, bir yili g'azot qilgan kishiga rahmat qilsin. U xalifalik haqini bor kuchi bilan ado etdi — zindiqlarni ta'qib qilib, bid'atchilarga tor keldi va musulmonlarni ularning yovuzligidan asradi.", "note": null},
  {"num": 107, "time": "00:09:54,040 --> 00:10:03,740", "arabic": "يَقُولُونَ أَنَّ قَلَنْسُوَتَهُ كَانَ مَكْتُوبًا عَلَيْهَا حَاجٌّ وَغَازٍ، رَحِمَهُ اللَّهُ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Aytishlaricha, uning kalapo'shiga «hoji va g'ozi» deb yozilgan ekan — Alloh unga rahmat qilsin. La havla va la quvvata illa billah.", "note": null},
  {"num": 110, "time": "00:10:18,960 --> 00:10:34,320", "arabic": "لِمَ قَلِلْ لَكَ إِنَّ الرَّجُلَ خَلَّى كُلَّ مَا حَوْلَهُ وَرَاحَ وَارْتَاحَ", "segs": null, "full_uz": "Senga aytmaganmidim — bu kishi atrofidagi hamma narsani tashlab, ketib, rohat topdi.", "note": null},
  {"num": 112, "time": "00:10:34,320 --> 00:10:41,500", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Assalomu alaykum. Va rahmatullohi va barakatuh.", "note": null},
  {"num": 114, "time": "00:10:49,720 --> 00:11:08,960", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي يَرْفَعُ وَيَضَعُ وَيُعْطِي وَيَمْنَعُ وَيَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ الْمَصِيرُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "segs": [{"ar": "اَلْحَمْدُ لِلَّهِ الَّذِي يَرْفَعُ وَيَضَعُ وَيُعْطِي وَيَمْنَعُ", "uz": "Ko'targuvchi va tushiruvchi, beruvchi va man qiluvchi Allohga hamd bo'lsin"}, {"ar": "وَيَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ الْمَصِيرُ", "uz": "tortib oluvchi va keng qiluvchi — qaytish Unga"}, {"ar": "وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ", "uz": "Guvohlik beramanki, Allohdan boshqa iloh yo'q, U yolg'iz, sherigi yo'q"}, {"ar": "وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "uz": "guvohlik beramanki, Muhammad Uning bandasi va rasulidir"}], "full_uz": "Ko'targuvchi va tushiruvchi, beruvchi va man qiluvchi, tortib oluvchi va keng qiluvchi Allohga hamd bo'lsin — qaytish Unga. Guvohlik beramanki, Allohdan boshqa iloh yo'q, U yolg'iz, sherigi yo'q, va guvohlik beramanki, Muhammad Uning bandasi va rasulidir.", "note": null},
  {"num": 117, "time": "00:11:08,960 --> 00:11:20,560", "arabic": "أَمَّا بَعْدُ، فَقَدِ اخْتَارَ اللَّهُ سُبْحَانَهُ وَتَعَالَى هَارُونَ الرَّشِيدَ إِلَى جِوَارِهِ", "segs": null, "full_uz": "Ammo ba'du: Alloh subhonahu va taolo Horun ar-Rashidni O'z huzuriga tanlab oldi.", "note": null},
  {"num": 120, "time": "00:11:20,560 --> 00:11:29,360", "arabic": "فَلَهُ الْحَمْدُ عَلَى وُقُوعِ مَا قَدْ سَبَقَ فِي عِلْمِهِ، وَنَفَذَ مِنْ قَضَائِهِ فِي خُلَفَائِهِ وَأَوْلِيَائِهِ", "segs": null, "full_uz": "Uning ilmida azaldan bo'lgan va xalifalari hamda avliyolari haqidagi qazosidan amalga oshgani uchun Unga hamd bo'lsin.", "note": null},
  {"num": 122, "time": "00:11:29,360 --> 00:11:39,799", "arabic": "قَالَ تَعَالَى: كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ، لَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ", "segs": null, "full_uz": "Alloh taolo aytdi: «Uning Zotidan boshqa har narsa halok bo'luvchidir — hukm Unikidir va Unga qaytariladi.»", "note": "Bu Qur'oni karim, Qasas surasi 88-oyatidan iqtibos."},
  {"num": 125, "time": "00:11:39,799 --> 00:11:49,460", "arabic": "فَأَحْمَدُوا اللَّهَ عَلَى مَا صَارَ إِلَيْهِ أَمِيرُ الْمُؤْمِنِينَ مِنْ عِظَمِ ثَوَابِهِ وَمُرَافَقَةِ أَنْبِيَائِهِ صَلَوَاتُ اللَّهِ عَلَيْهِمْ", "segs": null, "full_uz": "Amir al-Mo'mininning ulug' savobga va Alloh salovoti bo'lgan payg'ambarlar hamrohligiga yetganiga Allohga hamd ayting.", "note": null},
  {"num": 128, "time": "00:11:49,460 --> 00:12:03,779", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، وَإِيَّاهُ نَسْأَلُ أَنْ يُحْسِنَ الْخِلَافَةَ عَلَى أُمَّةِ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz — Undan Payg'ambari sollallohu alayhi va sallamning ummatiga xalifalikni yaxshi qilishini so'raymiz.", "note": null},
  {"num": 132, "time": "00:12:03,779 --> 00:12:13,320", "arabic": "فَقَدْ كَانَ عِصْمَةً وَكَهْفًا وَبِهِمْ رَؤُوفًا، أَقُولُ قَوْلِي هَذَا وَأَسْتَغْفِرُ اللَّهَ لِي وَلَكُمْ", "segs": [{"ar": "فَقَدْ كَانَ عِصْمَةً وَكَهْفًا وَبِهِمْ رَؤُوفًا", "uz": "U himoyachi va boshpana edi, ularga mehribon edi"}, {"ar": "أَقُولُ قَوْلِي هَذَا وَأَسْتَغْفِرُ اللَّهَ لِي وَلَكُمْ", "uz": "Shu so'zimni aytaman va o'zim hamda sizlar uchun Allohdan mag'firat so'rayman"}], "full_uz": "U himoyachi va boshpana edi, ularga mehribon edi. Shu so'zimni aytaman va o'zim hamda sizlar uchun Allohdan mag'firat so'rayman.", "note": null},
  {"num": 135, "time": "00:12:13,320 --> 00:12:30,320", "arabic": "هَذِهِ يَدِي تُبَايِعُكَ أَمِيرًا لِلْمُؤْمِنِينَ، عَلَى عَهْدِنَا الَّذِي قَطَعْنَاهُ عَلَى أَنْفُسِنَا لِأَمِيرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "segs": [{"ar": "هَذِهِ يَدِي تُبَايِعُكَ أَمِيرًا لِلْمُؤْمِنِينَ", "uz": "Mana bu qo'lim — seni Amir al-Mo'minin sifatida bay'at qilyapman"}, {"ar": "عَلَى عَهْدِنَا الَّذِي قَطَعْنَاهُ عَلَى أَنْفُسِنَا", "uz": "o'zimizga olgan ahdimiz asosida"}, {"ar": "لِأَمِيرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "uz": "Amir al-Mo'minin Horun ar-Rashid — Alloh unga rahmat qilsin — oldida"}], "full_uz": "Mana bu qo'lim — seni Amir al-Mo'minin sifatida bay'at qilyapman, Amir al-Mo'minin Horun ar-Rashid — Alloh unga rahmat qilsin — oldida o'zimizga olgan ahdimiz asosida.", "note": null},
  {"num": 138, "time": "00:12:30,320 --> 00:12:42,420", "arabic": "وَهَذِهِ يَدِي تُبَايِعُكَ أَمِيرًا لِلْمُؤْمِنِينَ، اِسْمَعُونِي يَا قَوْمِ", "segs": null, "full_uz": "Va mana bu qo'lim ham — seni Amir al-Mo'minin sifatida bay'at qilyapman. Meni eshiting, ey qavmim.", "note": null},
  {"num": 140, "time": "00:12:42,420 --> 00:12:52,680", "arabic": "لَقَدْ قُلْتُ لَكُمْ مَا لَدَيَّ، أَنَا لَنْ أَذْهَبَ أَبَدًا إِلَى خُرَاسَانَ، أَنَا مِنَ الْغَدِ عَائِدٌ إِلَى بَغْدَادَ", "segs": [{"ar": "لَقَدْ قُلْتُ لَكُمْ مَا لَدَيَّ", "uz": "Sizga bor gapimni aytdim"}, {"ar": "أَنَا لَنْ أَذْهَبَ أَبَدًا إِلَى خُرَاسَانَ", "uz": "men Xurosonga hech qachon bormayman"}, {"ar": "أَنَا مِنَ الْغَدِ عَائِدٌ إِلَى بَغْدَادَ", "uz": "men ertaga Bag'dodga qaytaman"}], "full_uz": "Sizga bor gapimni aytdim — men Xurosonga hech qachon bormayman, men ertaga Bag'dodga qaytaman.", "note": null},
  {"num": 143, "time": "00:12:52,680 --> 00:13:05,259", "arabic": "فَمَنْ أَرَادَ مُرَافَقَتِي إِلَى أَمِيرِ الْمُؤْمِنِينَ أَبِي مُوسَى الْأَمِينِ فَلْيَتَهَيَّأْ، وَمَنْ أَرَادَ الْخُرُوجَ إِلَى الْأَمِيرِ الْمَأْمُونِ فِي خُرَاسَانَ فَهَذَا شَأْنُهُ", "segs": [{"ar": "فَمَنْ أَرَادَ مُرَافَقَتِي إِلَى أَمِيرِ الْمُؤْمِنِينَ أَبِي مُوسَى الْأَمِينِ فَلْيَتَهَيَّأْ", "uz": "Kim men bilan Amir al-Mo'minin Abu Muso al-Aminga hamroh bo'lishni istasa, tayyorlansin"}, {"ar": "وَمَنْ أَرَادَ الْخُرُوجَ إِلَى الْأَمِيرِ الْمَأْمُونِ فِي خُرَاسَانَ فَهَذَا شَأْنُهُ", "uz": "kim Xurosondagi Amir al-Ma'munga chiqishni istasa, bu uning o'z ishi"}], "full_uz": "Kim men bilan Amir al-Mo'minin Abu Muso al-Aminga hamroh bo'lishni istasa, tayyorlansin — kim Xurosondagi Amir al-Ma'munga chiqishni istasa, bu uning o'z ishi.", "note": null},
  {"num": 147, "time": "00:13:05,259 --> 00:13:22,939", "arabic": "وَلَكِنْ يَا أَبَا الْعَبَّاسِ، وَصِيَّةُ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ أَنْ نَسْلُبَنَا بِأَيْدِينَا مِنْ مَالٍ وَسِلَاحٍ وَجُنْدٍ إِلَى الْأَمِيرِ الْمَأْمُونِ فِي خُرَاسَانَ", "segs": [{"ar": "وَلَكِنْ يَا أَبَا الْعَبَّاسِ، وَصِيَّةُ أَمِيرِ الْمُؤْمِنِينَ رَحِمَهُ اللَّهُ", "uz": "Ammo, Abu al-Abbos, Amir al-Mo'mininning — Alloh unga rahmat qilsin — vasiyati"}, {"ar": "أَنْ نَسْلُبَنَا بِأَيْدِينَا مِنْ مَالٍ وَسِلَاحٍ وَجُنْدٍ", "uz": "biz o'z qo'limiz bilan mol, qurol va askarni"}, {"ar": "إِلَى الْأَمِيرِ الْمَأْمُونِ فِي خُرَاسَانَ", "uz": "Xurosondagi Amir al-Ma'munga topshirishimiz edi"}], "full_uz": "Ammo, Abu al-Abbos, Amir al-Mo'mininning — Alloh unga rahmat qilsin — vasiyati, biz o'z qo'limiz bilan mol, qurol va askarni Xurosondagi Amir al-Ma'munga topshirishimiz edi.", "note": null},
  {"num": 152, "time": "00:13:22,939 --> 00:13:25,139", "arabic": "فَكَيْفَ نَعُودُ إِلَى بَغْدَادَ؟", "segs": null, "full_uz": "Unda biz Bag'dodga qanday qaytamiz?", "note": null},
  {"num": 153, "time": "00:13:29,139 --> 00:13:43,539", "arabic": "رَحِمَ اللَّهُ هَارُونَ الرَّشِيدَ وَأَسْكَنَهُ فَسِيحَ جِنَانِهِ، أَنَا مِنَ الْيَوْمِ أَمِيرِي وَسَيِّدِي وَمَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ أَبُو مُوسَى الْأَمِينُ", "segs": [{"ar": "رَحِمَ اللَّهُ هَارُونَ الرَّشِيدَ وَأَسْكَنَهُ فَسِيحَ جِنَانِهِ", "uz": "Alloh Horun ar-Rashidga rahmat qilib, uni jannatining kengligiga joylashtirsin"}, {"ar": "أَنَا مِنَ الْيَوْمِ أَمِيرِي وَسَيِّدِي وَمَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ أَبُو مُوسَى الْأَمِينُ", "uz": "Men bugundan boshlab amirim, sayyidim va xo'jayinim — Amir al-Mo'minin Abu Muso al-Amindir"}], "full_uz": "Alloh Horun ar-Rashidga rahmat qilib, uni jannatining kengligiga joylashtirsin. Men bugundan boshlab amirim, sayyidim va xo'jayinim — Amir al-Mo'minin Abu Muso al-Amindir.", "note": null},
  {"num": 155, "time": "00:13:43,539 --> 00:13:57,360", "arabic": "وَإِلَيْهِ مَقْصَدِي قَبْلَ غَيْرِهِ فَهُوَ أَمِيرُ الْمُؤْمِنِينَ بِبَيْعَةِ الْمُسْلِمِينَ، وَلَكِنَّ الْأَمِيرَ الْمَأْمُونَ هُوَ وَلِيُّ الْعَهْدِ الْآنَ وَذَلِكَ سَيُغْضِبُهُ بِلَا شَكٍّ", "segs": [{"ar": "وَإِلَيْهِ مَقْصَدِي قَبْلَ غَيْرِهِ فَهُوَ أَمِيرُ الْمُؤْمِنِينَ بِبَيْعَةِ الْمُسْلِمِينَ", "uz": "Boshqasidan avval maqsadim shu — u musulmonlarning bay'ati bilan Amir al-Mo'minindir"}, {"ar": "وَلَكِنَّ الْأَمِيرَ الْمَأْمُونَ هُوَ وَلِيُّ الْعَهْدِ الْآنَ وَذَلِكَ سَيُغْضِبُهُ بِلَا شَكٍّ", "uz": "Ammo Amir al-Ma'mun hozir valiahd, va bu uni albatta g'azablantiradi"}], "full_uz": "Boshqasidan avval maqsadim shu — u musulmonlarning bay'ati bilan Amir al-Mo'minindir. Ammo Amir al-Ma'mun hozir valiahd, va bu uni albatta g'azablantiradi.", "note": null},
  {"num": 157, "time": "00:13:57,360 --> 00:14:10,740", "arabic": "أَنَا لَا أَدَعُ مَلِكًا حَاضِرًا لِمَلِكٍ لَا أَدْرِي أَيَمْلِكُ أَمْ لَا، اَلرَّسَائِلُ الَّتِي جَاءَتْنِي مِنْ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ تَطْلُبُ مِنَّا الْعَوْدَةَ سَرِيعًا إِلَى بَغْدَادَ", "segs": [{"ar": "أَنَا لَا أَدَعُ مَلِكًا حَاضِرًا لِمَلِكٍ لَا أَدْرِي أَيَمْلِكُ أَمْ لَا", "uz": "Men hozir bor podshohni, hokimmi-yo'qmi bilmagan podshoh uchun tashlab qo'ymayman"}, {"ar": "اَلرَّسَائِلُ الَّتِي جَاءَتْنِي مِنْ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ", "uz": "Amir al-Mo'minin al-Amindan menga kelgan xatlar"}, {"ar": "تَطْلُبُ مِنَّا الْعَوْدَةَ سَرِيعًا إِلَى بَغْدَادَ", "uz": "bizdan tezda Bag'dodga qaytishni talab qilmoqda"}], "full_uz": "Men hozir bor podshohni, hokimmi-yo'qmi bilmagan podshoh uchun tashlab qo'ymayman. Amir al-Mo'minin al-Amindan menga kelgan xatlar bizdan tezda Bag'dodga qaytishni talab qilmoqda.", "note": null},
  {"num": 160, "time": "00:14:10,740 --> 00:14:21,980", "arabic": "فَانْظُرُوا مَنْ يَجِبُ عَلَيْكُمْ طَاعَتُهُ أَكْثَرَ، أَمِيرُ الْمُؤْمِنِينَ مَوْلَايَ الْأَمِينُ أَمْ وَلِيُّ الْعَهْدِ الْمَأْمُونُ", "segs": null, "full_uz": "Qarangchi — kimga itoat qilishingiz vojibroq: Amir al-Mo'minin, xo'jayinim al-Amin, yoki valiahd al-Ma'mun?", "note": null},
  {"num": 162, "time": "00:14:21,980 --> 00:14:32,259", "arabic": "اُنْظُرُوا عُمْرَكُمْ وَأَجْمِعُوا رَأْيَكُمْ ثُمَّ أَخْبِرُونِي، فَأَنَا خَارِجٌ عَمَّا قَرِيبٍ إِلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Umringizni o'ylab ko'ring, fikringizni bir joyga to'plang, keyin menga xabar bering — men tez orada Amir al-Mo'mininga chiqib ketaman.", "note": null},
  {"num": 164, "time": "00:14:51,980 --> 00:15:09,279", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatulloh.", "note": null},
  {"num": 166, "time": "00:15:09,279 --> 00:15:13,320", "arabic": "أَنْتَ أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ؟ أَجَلْ أَنَا هُوَ، خُذْ هَا", "segs": [{"ar": "أَنْتَ أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ؟", "uz": "Sen Ahmad ibn Hanbal ash-Shayboniymisan?"}, {"ar": "أَجَلْ أَنَا هُوَ، خُذْ هَا", "uz": "Ha, o'zim. Ol, mana."}], "full_uz": "Sen Ahmad ibn Hanbal ash-Shayboniymisan? Ha, o'zim. Ol, mana.", "note": null},
  {"num": 169, "time": "00:15:13,320 --> 00:15:24,879", "arabic": "مَا هَذَا؟ إِنَّهَا مِنْ عَطِيَّاتِ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ حَفِظَهُ اللَّهُ وَرَعَاهُ لِعُلَمَاءِ الْحَدِيثِ الشَّرِيفِ يَا أَبَا عَبْدِ اللَّهِ", "segs": [{"ar": "مَا هَذَا؟", "uz": "Bu nima?"}, {"ar": "إِنَّهَا مِنْ عَطِيَّاتِ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ حَفِظَهُ اللَّهُ وَرَعَاهُ", "uz": "Bu — Alloh saqlagan va asragan Amir al-Mo'minin al-Aminning in'omidir"}, {"ar": "لِعُلَمَاءِ الْحَدِيثِ الشَّرِيفِ يَا أَبَا عَبْدِ اللَّهِ", "uz": "sharif hadis olimlariga, Abu Abdulloh"}], "full_uz": "Bu nima? Bu — Alloh saqlagan va asragan Amir al-Mo'minin al-Aminning sharif hadis olimlariga in'omidir, Abu Abdulloh.", "note": null},
  {"num": 172, "time": "00:15:24,879 --> 00:15:31,240", "arabic": "وَمَا شَأْنِي بِهَا أَنَا؟ خُذْهَا إِنَّهَا مِنْ حَقِّكَ", "segs": null, "full_uz": "Bunga mening nima aloqam bor? Ol, bu sening haqqingdir.", "note": null},
  {"num": 174, "time": "00:15:31,240 --> 00:15:38,000", "arabic": "أَلَسْتَ مِنْ خِيرَةِ عُلَمَاءِ حَدِيثِ رَسُولِ اللَّهِ فِي بَغْدَادَ؟ لَسْتُ عَالِمًا فِي الْأَصْلِ حَتَّى أَكُونَ مِنْ خِيرَتِهِ", "segs": null, "full_uz": "Sen Bag'doddagi Rasululloh hadisi olimlarining sara vakillaridan emasmisan? Men aslida olim ham emasman, sarasidan bo'lay deb.", "note": null},
  {"num": 176, "time": "00:15:38,000 --> 00:15:47,180", "arabic": "يَبْدُو أَنَّكُمْ أَخْطَأْتُمُ الْبَيْتَ وَلَا شَكَّ، لَكِنْ يَا أَبَا عَبْدِ اللَّهِ، جَزَى اللَّهُ أَمِيرَ الْمُؤْمِنِينَ خَيْرًا وَجَزَاكُمْ مِثْلَهُ", "segs": [{"ar": "يَبْدُو أَنَّكُمْ أَخْطَأْتُمُ الْبَيْتَ وَلَا شَكَّ", "uz": "Siz uyni albatta adashib topgansiz"}, {"ar": "لَكِنْ يَا أَبَا عَبْدِ اللَّهِ، جَزَى اللَّهُ أَمِيرَ الْمُؤْمِنِينَ خَيْرًا وَجَزَاكُمْ مِثْلَهُ", "uz": "Ammo, Abu Abdulloh, Alloh Amir al-Mo'mininga yaxshilik bersin va sizga ham xuddi shunday"}], "full_uz": "Siz uyni albatta adashib topgansiz. Ammo, Abu Abdulloh, Alloh Amir al-Mo'mininga yaxshilik bersin va sizga ham xuddi shunday.", "note": null},
  {"num": 179, "time": "00:15:47,180 --> 00:15:54,660", "arabic": "أَخْطَأَ مَنْ دَلَّكُمْ عَلَيْهِ، وَعُذْرُونِي لَا أَسْتَطِيعُ قَبُولَ هَذَا الْمَالِ، كَمَا تَشَاءُ أَيُّهَا الرَّجُلُ", "segs": [{"ar": "أَخْطَأَ مَنْ دَلَّكُمْ عَلَيْهِ", "uz": "Sizga yo'l ko'rsatgan kishi xato qildi"}, {"ar": "وَعُذْرُونِي لَا أَسْتَطِيعُ قَبُولَ هَذَا الْمَالِ", "uz": "meni afv eting, bu mablag'ni qabul qila olmayman"}, {"ar": "كَمَا تَشَاءُ أَيُّهَا الرَّجُلُ", "uz": "Xohlaganingdek bo'lsin, ey odam"}], "full_uz": "Sizga yo'l ko'rsatgan kishi xato qildi — meni afv eting, bu mablag'ni qabul qila olmayman. Xohlaganingdek bo'lsin, ey odam.", "note": null},
  {"num": 182, "time": "00:15:54,660 --> 00:16:09,500", "arabic": "تَفَضَّلْ يَا عَمِّ، أَثَمَّ عَاقِلٌ يَفْعَلُ مَا فَعَلْتَ؟", "segs": null, "full_uz": "Marhamat, tog'a. Aqlli odam sen qilgan ishni qiladimi?", "note": null},
  {"num": 184, "time": "00:16:09,500 --> 00:16:15,720", "arabic": "أَنْتَ تَرْفُضُ النِّعْمَةَ؟ بَلْ شُبْهَةً يَا عَمِّ، أَمْوَالُ الدَّوْلَةِ لَا تَخْلُو مِنَ الشُّبُهَاتِ", "segs": [{"ar": "أَنْتَ تَرْفُضُ النِّعْمَةَ؟", "uz": "Sen ne'matni rad etyapsanmi?"}, {"ar": "بَلْ شُبْهَةً يَا عَمِّ", "uz": "Yo'q, shubha, tog'a"}, {"ar": "أَمْوَالُ الدَّوْلَةِ لَا تَخْلُو مِنَ الشُّبُهَاتِ", "uz": "davlat mol-mulki shubhalardan xoli emas"}], "full_uz": "Sen ne'matni rad etyapsanmi? Yo'q, shubha, tog'a — davlat mol-mulki shubhalardan xoli emas.", "note": null},
  {"num": 187, "time": "00:16:15,720 --> 00:16:23,480", "arabic": "قَدْ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِعِرْضِهِ وَدِينِهِ", "segs": null, "full_uz": "Payg'ambar sollallohu alayhi va sallam aytganlar: «Kim shubhali narsalardan tiyilsa, o'z or-nomusi va dinini poklagan bo'ladi.»", "note": "Bu Buxoriy va Muslim rivoyat qilgan mashhur hadis, halol-harom haqidagi."},
  {"num": 189, "time": "00:16:23,480 --> 00:16:33,680", "arabic": "لَكِنْ لِمَاذَا؟ إِنَّ عُلَمَاءَ بَغْدَادَ قَاطِبَةً فِيمَا أَعْلَمُ قَدْ قَبِلُوا عَطِيَّاتِ أَمِيرِ الْمُؤْمِنِينَ، وَتَأْتِي أَنْتَ وَتَرْفُضُهَا", "segs": [{"ar": "لَكِنْ لِمَاذَا؟", "uz": "Lekin nega?"}, {"ar": "إِنَّ عُلَمَاءَ بَغْدَادَ قَاطِبَةً فِيمَا أَعْلَمُ قَدْ قَبِلُوا عَطِيَّاتِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Men bilgan bo'yicha, Bag'doddagi barcha olimlar Amir al-Mo'mininning in'omini qabul qilishgan"}, {"ar": "وَتَأْتِي أَنْتَ وَتَرْفُضُهَا", "uz": "sen esa kelib rad etyapsan"}], "full_uz": "Lekin nega? Men bilgan bo'yicha, Bag'doddagi barcha olimlar Amir al-Mo'mininning in'omini qabul qilishgan, sen esa kelib rad etyapsan.", "note": null},
  {"num": 193, "time": "00:16:33,680 --> 00:16:38,340", "arabic": "كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ، وَلَا شَأْنَ لِي بِمَا يَفْعَلُهُ الْآخَرُونَ", "segs": null, "full_uz": "Har bir jon o'zi kasb qilgan narsaga garovdir — boshqalarning qilgan ishiga aloqam yo'q.", "note": "«كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ» — Muddassir surasi, 74:38-oyat."},
  {"num": 195, "time": "00:16:39,180 --> 00:16:50,960", "arabic": "ثُمَّ إِنَّ جَمَاعَةً مِنَ الصَّحَابَةِ قَدْ تَنَزَّهُوا عَنْ مَالِ السُّلْطَانِ، مِنْهُمْ حُذَيْفَةُ وَأَبُو عُبَيْدَةَ وَمُعَاذٌ وَأَبُو هُرَيْرَةَ وَابْنُ عُمَرَ، فَهَلْ أَدَعُ قَوْلَ الصَّحَابَةِ مِنْ أَجْلِ رَأْيٍ هُنَا أَوْ هُنَاكَ؟", "segs": [{"ar": "ثُمَّ إِنَّ جَمَاعَةً مِنَ الصَّحَابَةِ قَدْ تَنَزَّهُوا عَنْ مَالِ السُّلْطَانِ", "uz": "Yana, sahobalardan bir jamoat sulton molidan o'zini tiygan"}, {"ar": "مِنْهُمْ حُذَيْفَةُ وَأَبُو عُبَيْدَةَ وَمُعَاذٌ وَأَبُو هُرَيْرَةَ وَابْنُ عُمَرَ", "uz": "ular orasida Huzayfa, Abu Ubayda, Mu'oz, Abu Hurayra va Ibn Umar bor"}, {"ar": "فَهَلْ أَدَعُ قَوْلَ الصَّحَابَةِ مِنْ أَجْلِ رَأْيٍ هُنَا أَوْ هُنَاكَ؟", "uz": "Sahobalarning so'zini u yoki bu fikr uchun tashlaymanmi?"}], "full_uz": "Yana, sahobalardan bir jamoat sulton molidan o'zini tiygan — ular orasida Huzayfa, Abu Ubayda, Mu'oz, Abu Hurayra va Ibn Umar bor. Sahobalarning so'zini u yoki bu fikr uchun tashlaymanmi?", "note": null},
  {"num": 198, "time": "00:16:50,960 --> 00:16:57,320", "arabic": "فَهَلْ تَرَى أَنَّ مَالَ السُّلْطَانِ حَرَامٌ؟ لَا تَحْرِيمَ إِلَّا بِنَصٍّ، لَكِنْ أَحَبُّ إِلَيَّ أَنْ أَتَنَزَّهَ عَنْهُ", "segs": [{"ar": "فَهَلْ تَرَى أَنَّ مَالَ السُّلْطَانِ حَرَامٌ؟", "uz": "Sulton molini harom deb bilasanmi?"}, {"ar": "لَا تَحْرِيمَ إِلَّا بِنَصٍّ", "uz": "Nass bo'lmasa, harom deyilmaydi"}, {"ar": "لَكِنْ أَحَبُّ إِلَيَّ أَنْ أَتَنَزَّهَ عَنْهُ", "uz": "lekin men undan o'zimni tiyishni afzal ko'raman"}], "full_uz": "Sulton molini harom deb bilasanmi? Nass bo'lmasa, harom deyilmaydi — lekin men undan o'zimni tiyishni afzal ko'raman.", "note": null},
  {"num": 201, "time": "00:16:57,320 --> 00:17:02,600", "arabic": "فَالْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، ثُمَّ إِنَّنِي لَسْتُ بِحَاجَةٍ إِلَى هَذَا الْمَالِ", "segs": null, "full_uz": "Yuqori qo'l — quyi qo'ldan yaxshiroqdir. Yana, menga bu mablag' zarur emas.", "note": "«اَلْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى» — beruvchi qo'l oluvchi qo'ldan yaxshiroq, degan mashhur hadis."},
  {"num": 203, "time": "00:17:02,600 --> 00:17:08,519", "arabic": "بَلْ أَنْتَ فِي أَشَدِّ الْحَاجَةِ إِلَيْهِ، وَهَلْ هُنَاكَ أَحْوَجُ إِلَى الْمَالِ مِنْ طَالِبِ الْعِلْمِ؟", "segs": null, "full_uz": "Yo'q, senga eng ko'p shu kerak — ilm talabasidan boshqa pulga muhtojroq kim bor?", "note": null},
  {"num": 205, "time": "00:17:08,519 --> 00:17:16,960", "arabic": "وَأَنْتَ بَدَّلْتَ نَفْسَكَ وَعُمْرَكَ وَمَالَكَ فِي طَلَبِهِ، مَرَّةً إِلَى الْكُوفَةِ وَثَانِيَةً لِلْبَصْرَةِ وَثَالِثَةً إِلَى مَكَّةَ الْمُكَرَّمَةِ، وَرَابِعَةً وَخَامِسَةً", "segs": [{"ar": "وَأَنْتَ بَدَّلْتَ نَفْسَكَ وَعُمْرَكَ وَمَالَكَ فِي طَلَبِهِ", "uz": "Sen o'zingni, umringni va molingni uni izlashga sarflading"}, {"ar": "مَرَّةً إِلَى الْكُوفَةِ وَثَانِيَةً لِلْبَصْرَةِ", "uz": "bir marta Kufaga, ikkinchi Basraga"}, {"ar": "وَثَالِثَةً إِلَى مَكَّةَ الْمُكَرَّمَةِ، وَرَابِعَةً وَخَامِسَةً", "uz": "uchinchi Makka Mukarramaga, to'rtinchi va beshinchi marta"}], "full_uz": "Sen o'zingni, umringni va molingni uni izlashga sarflading — bir marta Kufaga, ikkinchi Basraga, uchinchi Makka Mukarramaga, to'rtinchi va beshinchi marta.", "note": null},
  {"num": 209, "time": "00:17:16,960 --> 00:17:25,759", "arabic": "وَأَنْتَ عَلَى ذَلِكَ لَا تَحْصُدُ مِنْ عِلْمِكَ إِلَّا الْمَشَقَّةَ وَالتَّعَبَ، أَفَلَا تَقْبَلُ مَا يُعِينُكَ عَلَى طَلَبِ الْعِلْمِ", "segs": [{"ar": "وَأَنْتَ عَلَى ذَلِكَ لَا تَحْصُدُ مِنْ عِلْمِكَ إِلَّا الْمَشَقَّةَ وَالتَّعَبَ", "uz": "Shunday bo'lsa-da, ilmingdan mashaqqat va charchoqdan boshqa hosil olmaysan"}, {"ar": "أَفَلَا تَقْبَلُ مَا يُعِينُكَ عَلَى طَلَبِ الْعِلْمِ", "uz": "ilm izlashga yordam beradigan narsani qabul qilmaysanmi?"}], "full_uz": "Shunday bo'lsa-da, ilmingdan mashaqqat va charchoqdan boshqa hosil olmaysan — ilm izlashga yordam beradigan narsani qabul qilmaysanmi?", "note": null},
  {"num": 212, "time": "00:17:25,759 --> 00:17:31,460", "arabic": "ثُمَّ أَلَيْسَ ذَلِكَ أَفْضَلَ مِنَ الْعَمَلِ عِنْدَ أَصْحَابِ الْحُقُولِ تَارَةً وَعِنْدَ أَصْحَابِ الْحَوَانِيتِ تَارَةً أُخْرَى", "segs": null, "full_uz": "Yana, bu — ba'zan dala egalari, ba'zan do'kon egalari yonida ishlashdan yaxshiroq emasmi?", "note": null},
  {"num": 214, "time": "00:17:31,460 --> 00:17:35,859", "arabic": "بَلْ عَمَلِي فِي ذَلِكَ أَفْضَلُ بِكَثِيرٍ مِنْ أَنْ أَقْبَلَ هِبَاتِ الْآخَرِينَ", "segs": null, "full_uz": "Yo'q, o'sha ishim boshqalarning ehsonlarini qabul qilishimdan ko'ra ancha yaxshiroqdir.", "note": null},
  {"num": 215, "time": "00:17:35,859 --> 00:17:51,120", "arabic": "عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَأَنْ يَأْخُذَ أَحَدُكُمْ أَحْبُلًا فَيَأْخُذَ حُزْمَةً مِنْ حَطَبٍ فَيَبِيعَ فَيَكُفَّ اللَّهُ بِهِ وَجْهَهُ خَيْرٌ مِنْ أَنْ يَسْأَلَ النَّاسَ", "segs": [{"ar": "عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ", "uz": "Zubayr ibn al-Avvomdan — Alloh undan rozi bo'lsin — Payg'ambar sollallohu alayhi va sallamdan rivoyat qilinadi, dedilar"}, {"ar": "لَأَنْ يَأْخُذَ أَحَدُكُمْ أَحْبُلًا فَيَأْخُذَ حُزْمَةً مِنْ حَطَبٍ فَيَبِيعَ", "uz": "Sizlardan birortangiz arqon olib, o'tin bog'lamini olib sotsa"}, {"ar": "فَيَكُفَّ اللَّهُ بِهِ وَجْهَهُ خَيْرٌ مِنْ أَنْ يَسْأَلَ النَّاسَ", "uz": "Alloh shu bilan uning yuzini saqlasa, bu odamlardan so'rashdan yaxshiroqdir"}], "full_uz": "Zubayr ibn al-Avvomdan — Alloh undan rozi bo'lsin — Payg'ambar sollallohu alayhi va sallamning: «Sizlardan birortangiz arqon olib, o'tin bog'lamini olib sotib, Alloh shu bilan uning yuzini (tilanchilikdan) saqlasa — bu odamlardan so'rashdan yaxshiroqdir», deganlari rivoyat qilingan.", "note": "Bu Buxoriy va Muslim rivoyat qilgan hadis, halol mehnat bilan tilanchilikdan saqlanish haqida."},
  {"num": 221, "time": "00:17:51,120 --> 00:17:52,500", "arabic": "أَعْطِي أَمْ مُنِعَ؟", "segs": null, "full_uz": "Berildimi yoki man qilindimi?", "note": null},
  {"num": 222, "time": "00:17:52,500 --> 00:17:59,240", "arabic": "هَلْ تَقُولِينَ شَيْئًا يَا أُمَّ أَحْمَدَ؟ أَحْمَدُ يَفْعَلُ ذَلِكَ بَعْدَ عِلْمٍ يَا أَبَا حَنْبَلٍ", "segs": null, "full_uz": "Biror gap aytasizmi, Ummu Ahmad? Ahmad buni bilib qilyapti, Abu Hanbal.", "note": null},
  {"num": 224, "time": "00:17:59,240 --> 00:18:05,220", "arabic": "مَا أَرَاكِ إِلَّا رَضِيَّةً بِمَا يَجْدُرُ بِكِ أَنْ تَلُومِيهِ عَلَيْهِ، مَنْ كَانَ مِثْلِي وَمِثْلَكِ", "segs": null, "full_uz": "Uni koyishing lozim bo'lgan narsaga rozi bo'lganingni ko'ryapman — men va senga o'xshaganlar bilan solishtirganda.", "note": null},
  {"num": 226, "time": "00:18:05,220 --> 00:18:13,740", "arabic": "لَا يَلُومُ مَنْ كَانَ مِثْلَ أَحْمَدَ يَا إِسْحَاقَ، كَمَا تَشَاؤُونَ، كَمَا تَشَاؤُونَ", "segs": null, "full_uz": "Ahmadga o'xshagan kishini koyimaydi, Ishoq. Xohlaganingizcha, xohlaganingizcha.", "note": null},
  {"num": 229, "time": "00:18:13,740 --> 00:18:22,299", "arabic": "أَنَا لَا أَدْرِي لِمَ أُكَابِدُ كُلَّ الْمَشَقَّةِ وَالتَّعَبِ فِي إِقْنَاعِ مَنْ بَقِيَ عُمُرُهُ صُلْبَ الرَّأْسِ وَلَا سَبِيلَ لِإِقْنَاعِهِ", "segs": [{"ar": "أَنَا لَا أَدْرِي لِمَ أُكَابِدُ كُلَّ الْمَشَقَّةِ وَالتَّعَبِ", "uz": "Bilmayman — nega shuncha mashaqqat va charchoq chekaman"}, {"ar": "فِي إِقْنَاعِ مَنْ بَقِيَ عُمُرُهُ صُلْبَ الرَّأْسِ", "uz": "umri bo'yi qattiq boshli qolgan kishini ko'ndirish uchun"}, {"ar": "وَلَا سَبِيلَ لِإِقْنَاعِهِ", "uz": "va uni ishontirib bo'lmaydi"}], "full_uz": "Bilmayman — nega men umri bo'yi qattiq boshli qolgan, ishontirib bo'lmaydigan kishini ko'ndirish uchun shuncha mashaqqat va charchoq chekaman.", "note": null},
  {"num": 232, "time": "00:18:22,299 --> 00:18:31,740", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، غَرِيبٌ وَلَعُ النَّاسِ بِالدُّنْيَا وَزِينَتِهَا هَكَذَا", "segs": null, "full_uz": "La havla va la quvvata illa billah. Odamlarning dunyo va uning ziynatiga bunday berilishi g'aroyibdir.", "note": null},
  {"num": 234, "time": "00:18:32,440 --> 00:18:37,240", "arabic": "لَدَيْنَا قُوتُ يَوْمِنَا وَلَسْنَا بِحَاجَةٍ إِلَى أَحَدٍ إِلَّا لِلَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Bizda kunlik rizqimiz bor va Alloh azza va jalladan boshqa hech kimga muhtoj emasmiz.", "note": null},
  {"num": 237, "time": "00:18:37,240 --> 00:18:43,259", "arabic": "لَا يُثِيرَنَّ حَفِيظَتَكَ كَلَامُ عَمِّكَ يَا بُنَيَّ، فَمَا أَرَادَ لَكَ إِلَّا الْخَيْرَ", "segs": null, "full_uz": "Amakingning gapi seni g'azablantirmasin, o'g'lim — u senga faqat yaxshilikni istagan.", "note": null},
  {"num": 239, "time": "00:18:43,259 --> 00:18:50,640", "arabic": "لَيْسَ شَكِّي فِي نِيَّتِهِ وَقَصْدِهِ يَا أُمَّهْ، إِنَّمَا شَكِّي فِي صَوَابِهَا، صَدَقْتَ", "segs": null, "full_uz": "Shubham uning niyati va maqsadida emas, onajon — shubham to'g'riligida. To'g'ri aytding.", "note": null},
  {"num": 242, "time": "00:18:50,640 --> 00:19:02,720", "arabic": "أُرِيدُ أَنْ أَعْرِفَ مَا جَرَى بَيْنَكَ وَبَيْنَ ابْنِ هَارُونَ، اَلْحَقُّ أَنَّنِي لَمْ أُفَاتِحْهُ فِي أَمْرِكَ يَا أَبَا عَبْدِ الرَّحْمَنِ", "segs": null, "full_uz": "Sen bilan Horunning o'g'li o'rtasida nima bo'lganini bilishni istayman. Haqiqatan ham, sening masalangda hali unga so'z ochmaganman, Abu Abd ar-Rahmon.", "note": null},
  {"num": 244, "time": "00:19:02,720 --> 00:19:09,799", "arabic": "لَمْ أَجِدِ الْفُرْصَةَ سَانِحَةً بَعْدُ، وَمَا تَتَجِدُ أَنَّ الْفُرْصَةَ مُنَاسِبَةٌ؟", "segs": null, "full_uz": "Hali qulay fursat topmadim. Qachon fursat munosib bo'ladi deb bilasan?", "note": null},
  {"num": 246, "time": "00:19:09,799 --> 00:19:21,180", "arabic": "لَا أَدْرِي يَا أَبَا عَبْدِ الرَّحْمَنِ، فَالْأَمِينُ هَذَا مُتَقَلِّبُ الْمِزَاجِ، كَمَا أَنَّهُ مُنْشَغِلٌ الْآنَ وَلَا أَعْرِفُ مَوْقِفَهُ تُجَاهِي", "segs": [{"ar": "لَا أَدْرِي يَا أَبَا عَبْدِ الرَّحْمَنِ", "uz": "Bilmayman, Abu Abd ar-Rahmon"}, {"ar": "فَالْأَمِينُ هَذَا مُتَقَلِّبُ الْمِزَاجِ، كَمَا أَنَّهُ مُنْشَغِلٌ الْآنَ", "uz": "bu al-Amin kayfiyati beqaror odam, hozir ham band"}, {"ar": "وَلَا أَعْرِفُ مَوْقِفَهُ تُجَاهِي", "uz": "va uning menga munosabatini bilmayman"}], "full_uz": "Bilmayman, Abu Abd ar-Rahmon — bu al-Amin kayfiyati beqaror odam, hozir ham band, va uning menga munosabatini bilmayman.", "note": null},
  {"num": 250, "time": "00:19:21,180 --> 00:19:27,660", "arabic": "عَلَيْكَ بِالصَّبْرِ قَلِيلًا يَا أَبَا عَبْدِ الرَّحْمَنِ، وَإِيَّاكَ أَنْ تُغَادِرَ مَخْبَأَكَ حَتَّى أُعْلِمَكَ بِذَلِكَ", "segs": null, "full_uz": "Biroz sabr qil, Abu Abd ar-Rahmon — men senga xabar bermaguncha yashiningan joyingdan chiqma.", "note": null},
  {"num": 252, "time": "00:19:27,660 --> 00:19:33,559", "arabic": "عُيُونُ الْأَمِينِ فِي كُلِّ مَكَانٍ، وَلَا نُرِيدُ لِلْعَجَلَةِ أَنْ تُوقِعَنَا فِي خَطَإٍ", "segs": null, "full_uz": "Al-Aminning ko'zlari hamma yerda — shoshqaloqlik bizni xatoga solishini xohlamaymiz.", "note": null},
  {"num": 254, "time": "00:19:33,559 --> 00:19:45,100", "arabic": "فَأَنْتَ مَا زِلْتَ عَلَى رَأْسِ الْمَطْلُوبِينَ، اِطْمَئِنَّ، سَأَبْذُلُ جُهْدِي، عَلِّمْنِي إِنِ اسْتَجَدَّ مَعَكَ شَيْءٌ", "segs": [{"ar": "فَأَنْتَ مَا زِلْتَ عَلَى رَأْسِ الْمَطْلُوبِينَ، اِطْمَئِنَّ", "uz": "Sen hamon qidiruvdagilarning boshida turibsan — xotirjam bo'l"}, {"ar": "سَأَبْذُلُ جُهْدِي", "uz": "Kuchimni ayamayman"}, {"ar": "عَلِّمْنِي إِنِ اسْتَجَدَّ مَعَكَ شَيْءٌ", "uz": "Yangi bir narsa bo'lsa, menga bildir"}], "full_uz": "Sen hamon qidiruvdagilarning boshida turibsan — xotirjam bo'l. Kuchimni ayamayman. Yangi bir narsa bo'lsa, menga bildir.", "note": null},
  {"num": 258, "time": "00:19:45,100 --> 00:19:51,680", "arabic": "سَأَفْعَلُ إِنْ شَاءَ اللَّهُ، رَافَقَتْكَ السَّلَامَةُ يَا أَبَا عَبْدِ الرَّحْمَنِ، رَافَقَتْكَ السَّلَامَةُ", "segs": null, "full_uz": "Alloh xohlasa, shunday qilaman. Omonlik senga hamroh bo'lsin, Abu Abd ar-Rahmon. Omonlik senga hamroh bo'lsin.", "note": null},
  {"num": 261, "time": "00:19:51,680 --> 00:20:03,960", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Assalomu alaykum va rahmatullohi va barakatuh. Va alaykum assalom va rahmatullohi va barakatuh.", "note": null},
  {"num": 263, "time": "00:20:05,480 --> 00:20:08,100", "arabic": "لَقَدْ وَقَعَ مَا كُنَّا نَخْشَاهُ يَا مَوْلَايَ", "segs": null, "full_uz": "Qo'rqib turgan narsamiz yuz berdi, xo'jayinim.", "note": null},
  {"num": 264, "time": "00:20:08,099 --> 00:20:12,579", "arabic": "وَهُوَ؟ اِبْنُ الرَّبِيعِ", "segs": null, "full_uz": "Nima ekan? Ibn ar-Rabi'.", "note": null},
  {"num": 266, "time": "00:20:12,579 --> 00:20:18,339", "arabic": "اِبْنُ الرَّبِيعِ لَمْ يُقْدِمْ إِلَى مَرْوَ كَمَا كُنَّا نَتَوَقَّعُ، بَلْ عَادَ إِلَى بَغْدَادَ", "segs": null, "full_uz": "Ibn ar-Rabi' kutganimizdek Marvga kelmadi — aksincha, Bag'dodga qaytdi.", "note": null},
  {"num": 268, "time": "00:20:18,339 --> 00:20:28,679", "arabic": "اِجْلِسْ يَا أَبَا الْعَبَّاسِ، كَيْفَ ذَلِكَ؟", "segs": null, "full_uz": "O'tir, Abu al-Abbos. Bu qanday bo'ldi?", "note": null},
  {"num": 270, "time": "00:20:28,679 --> 00:20:39,759", "arabic": "لَقَدْ ضَرَبَ بِوَصِيَّةِ أَمِيرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ عَرْضَ الْحَائِطِ، وَلَمْ يُقْدِمْ عَلَيْكَ لَا بِالسِّلَاحِ وَلَا بِالرِّجَالِ وَلَا بِالْمَالِ كَمَا أَوْصَاهُ، بَلْ عَادَ بِهِمْ إِلَى بَغْدَادَ", "segs": [{"ar": "لَقَدْ ضَرَبَ بِوَصِيَّةِ أَمِيرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ عَرْضَ الْحَائِطِ", "uz": "U Amir al-Mo'minin Horun ar-Rashidning — Alloh unga rahmat qilsin — vasiyatini butunlay chetga uloqtirdi"}, {"ar": "وَلَمْ يُقْدِمْ عَلَيْكَ لَا بِالسِّلَاحِ وَلَا بِالرِّجَالِ وَلَا بِالْمَالِ كَمَا أَوْصَاهُ", "uz": "Vasiyat qilinganidek, senga qurol, odam yoki mol bilan kelmadi"}, {"ar": "بَلْ عَادَ بِهِمْ إِلَى بَغْدَادَ", "uz": "aksincha, ularni Bag'dodga qaytarib olib ketdi"}], "full_uz": "U Amir al-Mo'minin Horun ar-Rashidning — Alloh unga rahmat qilsin — vasiyatini butunlay chetga uloqtirdi. Vasiyat qilinganidek, senga qurol, odam yoki mol bilan kelmadi, aksincha, ularni Bag'dodga qaytarib olib ketdi.", "note": null},
  {"num": 273, "time": "00:20:39,759 --> 00:20:46,779", "arabic": "أَمَعْتُوهٌ هَذَا؟ أَنَا أَنْتَظِرُ قُدُومَهُ عَلَيَّ بِرِجَالِي وَأَمْوَالِي وَالسِّلَاحِ، وَهُوَ يَعُودُ بِهَا إِلَى بَغْدَادَ؟", "segs": null, "full_uz": "Bu telbami? Men uning odamlarim, mollarim va qurollarim bilan kelishini kutyapman-u, u ularni Bag'dodga qaytarib olib ketyaptimi?", "note": null},
  {"num": 276, "time": "00:20:48,740 --> 00:20:54,059", "arabic": "هَذَا الَّذِي حَدَثَ، اِبْنُ الرَّبِيعِ لَا يَنْفَكُّ عَنْ خُبْثِهِ", "segs": null, "full_uz": "Bo'lgani shu — Ibn ar-Rabi' o'z makridan qaytmaydi.", "note": null},
  {"num": 278, "time": "00:20:54,059 --> 00:21:06,220", "arabic": "أَرْسِلْ لَهُ جُنْدًا يَأْتُونَ بِهِ صَاغِرًا إِلَى خُرَاسَانَ، لِنَرَى رَأْيَنَا فِيهِ، أُقْسِمُ لَأَجْعَلَنَّهُ يَنْدَمُ عَلَى مُخَالَفَتِهِ وَصِيَّةَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "segs": [{"ar": "أَرْسِلْ لَهُ جُنْدًا يَأْتُونَ بِهِ صَاغِرًا إِلَى خُرَاسَانَ", "uz": "Unga qo'shin yubor — uni xor holda Xurosonga olib kelishsin"}, {"ar": "لِنَرَى رَأْيَنَا فِيهِ", "uz": "fikrimizni ko'rsatamiz"}, {"ar": "أُقْسِمُ لَأَجْعَلَنَّهُ يَنْدَمُ عَلَى مُخَالَفَتِهِ وَصِيَّةَ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "uz": "Qasam ichamanki, Horun ar-Rashidning — Alloh unga rahmat qilsin — vasiyatiga qarshi chiqqanidan pushaymon qildiraman"}], "full_uz": "Unga qo'shin yubor — uni xor holda Xurosonga olib kelishsin, fikrimizni ko'rsatamiz. Qasam ichamanki, Horun ar-Rashidning — Alloh unga rahmat qilsin — vasiyatiga qarshi chiqqanidan pushaymon qildiraman.", "note": null},
  {"num": 282, "time": "00:21:07,779 --> 00:21:11,960", "arabic": "وَغَيْرُ ذَلِكَ يَا مَوْلَايَ؟ وَمَاذَا غَيْرُ ذَلِكَ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Bundan boshqa nima bor, xo'jayinim? Bundan boshqa nima bor, Abu al-Abbos?", "note": null},
  {"num": 284, "time": "00:21:11,960 --> 00:21:20,079", "arabic": "أَرَى أَنَّكَ إِنْ فَعَلْتَ ذَلِكَ أَثَرْتَ حَفِيظَةَ أَخِيكَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Menimcha, buni qilsang, akang Amir al-Mo'mininning g'azabini qo'zg'atasan.", "note": null},
  {"num": 286, "time": "00:21:20,079 --> 00:21:34,019", "arabic": "اَلرَّأْيُ يَا مَوْلَايَ أَنْ نَتْرُكَهُمْ لِيَصِلُوا إِلَى بَغْدَادَ، وَبَعْدَ لِقَائِهِمْ أَخِيكَ الْأَمِينِ سَيُفْصِحُونَ عَنْ نَوَايَاهُمْ، حِينَهَا نَتَصَرَّفُ", "segs": [{"ar": "اَلرَّأْيُ يَا مَوْلَايَ أَنْ نَتْرُكَهُمْ لِيَصِلُوا إِلَى بَغْدَادَ", "uz": "Fikrim shuki, xo'jayinim — ularni Bag'dodga yetib borishlariga qo'yib beraylik"}, {"ar": "وَبَعْدَ لِقَائِهِمْ أَخِيكَ الْأَمِينِ سَيُفْصِحُونَ عَنْ نَوَايَاهُمْ", "uz": "Akangiz al-Amin bilan uchrashgandan keyin niyatlarini oshkor qilishadi"}, {"ar": "حِينَهَا نَتَصَرَّفُ", "uz": "o'shanda choralar ko'ramiz"}], "full_uz": "Fikrim shuki, xo'jayinim — ularni Bag'dodga yetib borishlariga qo'yib beraylik. Akangiz al-Amin bilan uchrashgandan keyin niyatlarini oshkor qilishadi, o'shanda choralar ko'ramiz.", "note": null},
  {"num": 291, "time": "00:21:37,779 --> 00:21:47,879", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh. Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 293, "time": "00:21:47,879 --> 00:21:58,259", "arabic": "لَا تُخْبِرْهُ إِذَنْ، أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "segs": null, "full_uz": "Unda unga aytma. Alloh taologa la'natlangan shaytondan sig'inaman.", "note": null},
  {"num": 295, "time": "00:21:58,259 --> 00:22:05,980", "arabic": "كَيْفَ تُرِيدُ أَنْ أُخْفِيَ شَيْئًا كَهَذَا عَنْ أَبِي عَبْدِ اللَّهِ يَا أَبَا زَكَرِيَّا؟ إِذَنْ حَالُكَ كَحَالِ بَقِيَّةِ الْقَوْمِ", "segs": null, "full_uz": "Bunday narsani Abu Abdullohdan qanday yashirishimni istaysan, Abu Zakariyo? Unda holing boshqalarning holidek ekan.", "note": null},
  {"num": 297, "time": "00:22:05,980 --> 00:22:09,539", "arabic": "أَبُو عَبْدِ اللَّهِ هُوَ الِاسْتِثْنَاءُ، لَا نَحْنُ", "segs": null, "full_uz": "Abu Abdulloh — bu istisno. Biz emas.", "note": null},
  {"num": 299, "time": "00:22:09,539 --> 00:22:29,559", "arabic": "اَلسَّلَامُ عَلَيْكُمْ يَا أَبَا عَبْدِ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ، اَللَّهُمَّ آمِينَ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Assalomu alaykum, Abu Abdulloh. Assalomu alaykum. Allohumma, omin. Va alaykum assalom va rahmatullohi va barakatuh.", "note": null},
  {"num": 303, "time": "00:22:30,559 --> 00:22:35,960", "arabic": "يَا أَبَا عَبْدِ اللَّهِ، أُرِيدُ أَنْ أَقُولَ لَكَ شَيْئًا، أَعْرِفُ مَا تُرِيدُ أَنْ تَقُولَ", "segs": null, "full_uz": "Abu Abdulloh, senga bir narsa aytmoqchiman. Nima aytmoqchi ekaningni bilaman.", "note": null},
  {"num": 306, "time": "00:22:35,960 --> 00:22:41,759", "arabic": "وَكَأَنَّكَ كُنْتَ بِحَاجَةٍ لِهَذَا الْمَالِ حَتَّى تَأْخُذَهُ، أَنَا؟", "segs": null, "full_uz": "Go'yo bu mablag'ga muhtoj bo'lganingdan olgan bo'lardim, deysanmi? Men-a?", "note": null},
  {"num": 308, "time": "00:22:41,759 --> 00:22:48,420", "arabic": "لَسْتُ بِحَاجَةٍ إِلَيْهِ وَأَنْتَ تَعْلَمُ ذَلِكَ، وَلَكِنْ خَشِيتُ أَنْ يُثِيرَ حَفِيظَتَهُمْ عَلَيَّ", "segs": null, "full_uz": "Unga muhtoj emasman, buni bilasan — lekin ularning menga g'azabini qo'zg'atishidan qo'rqdim.", "note": null},
  {"num": 310, "time": "00:22:48,420 --> 00:22:56,580", "arabic": "رَفْضُ عَطِيَّةِ أَمِيرِ الْمُؤْمِنِينَ، أَتَخْشَوْنَهُمْ فَاللَّهُ أَحَقُّ أَنْ تَخْشَوْهُ؟ أَلَمْ يَسَعْكَ مَا وَسِعَ غَيْرَكَ؟", "segs": [{"ar": "رَفْضُ عَطِيَّةِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Amir al-Mo'mininning in'omini rad etish"}, {"ar": "أَتَخْشَوْنَهُمْ فَاللَّهُ أَحَقُّ أَنْ تَخْشَوْهُ؟", "uz": "Ulardan qo'rqasizmi — Alloh qo'rqishga loyiqroq-ku?"}, {"ar": "أَلَمْ يَسَعْكَ مَا وَسِعَ غَيْرَكَ؟", "uz": "Boshqalarga yetgan narsa senga yetmadimi?"}], "full_uz": "Amir al-Mo'mininning in'omini rad etish. Ulardan qo'rqasizmi — Alloh qo'rqishga loyiqroq-ku? Boshqalarga yetgan narsa senga yetmadimi?", "note": null},
  {"num": 313, "time": "00:22:56,580 --> 00:23:04,400", "arabic": "لَا أَعْرِفُ أَحَدًا عَنْ غَيْرِكَ رَفَضَ ذَلِكَ يَا أَبَا عَبْدِ اللَّهِ، وَإِنَّمَا فَعَلْتُ أَنَا مَا فَعَلَتِ الْجَمَاعَةُ، اَلْجَمَاعَةُ؟", "segs": null, "full_uz": "Sendan boshqa buni rad etgan birortasini bilmayman, Abu Abdulloh — men jamoat qilganini qildim. Jamoatmi?", "note": null},
  {"num": 316, "time": "00:23:04,400 --> 00:23:09,740", "arabic": "هَجَلِ الْجَمَاعَةِ! فَشُيُوخُنَا كُلُّهُمْ لَمْ يَرْفُضُوا ذَلِكَ الْمَالَ، لَيْسَ ذَلِكَ وَقْفًا عَلَيَّ", "segs": null, "full_uz": "Qanday jamoat! Shayxlarimizning barchasi bu molni rad etishmagan. Bu faqat menga xos emas.", "note": null},
  {"num": 318, "time": "00:23:09,740 --> 00:23:20,300", "arabic": "إِذَا كُنْتَ وَحْدَكَ عَلَى الْحَقِّ فَأَنْتَ الْجَمَاعَةُ، إِذَنْ أَنْتَ تَرَى أَنَّ الْمَالَ حَرَامٌ يَا أَبَا عَبْدِ اللَّهِ، وَمَنْ أَكُونُ حَتَّى أُحَرِّمَ وَأُحَلِّلَ", "segs": [{"ar": "إِذَا كُنْتَ وَحْدَكَ عَلَى الْحَقِّ فَأَنْتَ الْجَمَاعَةُ", "uz": "Agar yolg'iz o'zing haq bo'lsang, sen jamoatsan"}, {"ar": "إِذَنْ أَنْتَ تَرَى أَنَّ الْمَالَ حَرَامٌ يَا أَبَا عَبْدِ اللَّهِ", "uz": "Unda molni harom deb bilasan, Abu Abdulloh?"}, {"ar": "وَمَنْ أَكُونُ حَتَّى أُحَرِّمَ وَأُحَلِّلَ", "uz": "Men kim bo'ldim, harom yoki halol qilsam?"}], "full_uz": "Agar yolg'iz o'zing haq bo'lsang, sen jamoatsan. Unda molni harom deb bilasan, Abu Abdulloh? Men kim bo'ldim, harom yoki halol qilsam?", "note": null},
  {"num": 321, "time": "00:23:20,300 --> 00:23:27,880", "arabic": "أَعُوذُ بِاللَّهِ أَنْ أَقُولَ عَلَى اللَّهِ مَا لَيْسَ لِي بِهِ عِلْمٌ، إِنَّمَا أَغْنَانَا اللَّهُ عَنِ السَّلَاطِينِ وَأَمْوَالِهِمْ", "segs": null, "full_uz": "Allohga sig'inaman, bilmagan narsamni Alloh haqida aytishdan — Alloh bizni sultonlar va ularning mollaridan behojat qilgan, xolos.", "note": null},
  {"num": 323, "time": "00:23:27,880 --> 00:23:32,400", "arabic": "فَمَا حَاجَتُنَا لِمَا أَغْنَانَا اللَّهُ عَنْهُ؟", "segs": null, "full_uz": "Alloh bizni undan behojat qilgan narsaga bizning nima hojatimiz bor?", "note": null},
  {"num": 324, "time": "00:23:32,400 --> 00:23:42,080", "arabic": "اِعْلَمْ يَا أَبَا الْمُغِيرَةِ، إِنَّ أَكْثَرَ مَا يَدْفَعُهُ السَّلَاطِينُ مِنْ مَالٍ لِأَهْلِ الْعِلْمِ إِنَّمَا هُوَ لِاسْتِمَالَتِهِمْ وَلِيَكُونَ لَهُمْ يَدٌ عَلَيْهِمْ", "segs": [{"ar": "اِعْلَمْ يَا أَبَا الْمُغِيرَةِ", "uz": "Bilib qo'y, Abu al-Mug'ira"}, {"ar": "إِنَّ أَكْثَرَ مَا يَدْفَعُهُ السَّلَاطِينُ مِنْ مَالٍ لِأَهْلِ الْعِلْمِ", "uz": "sultonlar ilm ahliga to'laydigan mablag'ning ko'pi"}, {"ar": "إِنَّمَا هُوَ لِاسْتِمَالَتِهِمْ وَلِيَكُونَ لَهُمْ يَدٌ عَلَيْهِمْ", "uz": "ularni o'ziga moyil qilish va ular ustidan qo'l-hukmronlik hosil qilish uchundir"}], "full_uz": "Bilib qo'y, Abu al-Mug'ira — sultonlar ilm ahliga to'laydigan mablag'ning ko'pi ularni o'ziga moyil qilish va ular ustidan qo'l-hukmronlik hosil qilish uchundir.", "note": null},
  {"num": 327, "time": "00:23:50,360 --> 00:23:56,120", "arabic": "وَمَا حَاجَتُكَ إِلَى الرَّحِيلِ يَا أَبَا عَبْدِ اللَّهِ، وَأَنْتَ تَتَصَدَّرُ حَلَقَاتِ الْعِلْمِ فِي الْحَرَمِ", "segs": null, "full_uz": "Ketishga nima hojating bor, Abu Abdulloh — Haramda ilm halqalarida boshchilik qilib turibsan-ku?", "note": null},
  {"num": 329, "time": "00:23:56,120 --> 00:24:09,480", "arabic": "وَإِلَيْكَ يَفِضُّ الطُّلَّابُ مِنْ شَتَّى الْأَمْصَارِ وَالْبِقَاعِ، اَلْعِلْمُ أَمَانَةٌ يَا حَمْدَهْ", "segs": null, "full_uz": "Har xil shahar va o'lkalardan talabalar sening huzuringga oqib kelishadi. Ilm — omonat, Hamda.", "note": null},
  {"num": 331, "time": "00:24:09,480 --> 00:24:15,440", "arabic": "أَمَانَةٌ وَبَرِيدٌ يَجِبُ أَنْ يَصِلَ إِلَى طُلَّابِهِ وَأَصْحَابِهِ", "segs": null, "full_uz": "Omonat va xat — o'z talabalari va egalariga yetib borishi kerak.", "note": null},
  {"num": 333, "time": "00:24:15,440 --> 00:24:22,140", "arabic": "هُنَا فِي مَكَّةَ دَرَّسْتُهُ لِكَثِيرٍ مِنَ الطَّلَبَةِ، وَلَمْ يَعُدْ لَدَيَّ مَا أَزِيدُ عَلَيْهِ", "segs": null, "full_uz": "Bu yerda, Makkada, uni ko'p talabalarga o'rgatdim, endi ustiga qo'shadigan narsam qolmadi.", "note": null},
  {"num": 335, "time": "00:24:22,140 --> 00:24:41,259", "arabic": "أَمَّا فِي بَغْدَادَ، فَهُنَاكَ حَاضِرَةُ الْخِلَافَةِ، وَحَاضِنَةُ الْعُلَمَاءِ وَالْفُقَهَاءِ، وَمَحْضَنُ الطَّلَبَةِ وَالدَّارِسِينَ، وَبَرَكَةُ الْعِلْمِ يَا حَمْدَى تَتَأَتَّى فِي الْأَخْذِ وَالرَّدِّ بَيْنَ أَصْحَابِهِ", "segs": [{"ar": "أَمَّا فِي بَغْدَادَ، فَهُنَاكَ حَاضِرَةُ الْخِلَافَةِ", "uz": "Bag'dodda esa xalifalik poytaxti bor"}, {"ar": "وَحَاضِنَةُ الْعُلَمَاءِ وَالْفُقَهَاءِ، وَمَحْضَنُ الطَّلَبَةِ وَالدَّارِسِينَ", "uz": "olimlar va fuqahoning tarbiya markazi, talaba va o'quvchilarning uyi bor"}, {"ar": "وَبَرَكَةُ الْعِلْمِ يَا حَمْدَى تَتَأَتَّى فِي الْأَخْذِ وَالرَّدِّ بَيْنَ أَصْحَابِهِ", "uz": "ilmning barakati, Hamda, uning egalari o'rtasidagi munozarada hosil bo'ladi"}], "full_uz": "Bag'dodda esa xalifalik poytaxti, olimlar va fuqahoning tarbiya markazi, talaba va o'quvchilarning uyi bor — ilmning barakati, Hamda, uning egalari o'rtasidagi olib-berish (munozara)da hosil bo'ladi.", "note": null},
  {"num": 341, "time": "00:24:41,259 --> 00:24:52,759", "arabic": "أَلَا تَقُولِينَ شَيْئًا يَا عَمَّتِي؟ وَمَاذَا تُرِيدِينَ أَنْ أَقُولَ يَا ابْنَتِي؟", "segs": null, "full_uz": "Biror narsa demaysizmi, ammaxon? Nima deyishimni istaysan, qizim?", "note": null},
  {"num": 343, "time": "00:24:53,380 --> 00:25:03,000", "arabic": "زَوْجُكِ أَدْرَى بِمَا يُصْلِحُ لَهُ وَلَنَا فِي الدِّينِ وَالدُّنْيَا، وَأَنْتِ تَعْرِفِينَ أَنَّهُ نَذَرَ نَفْسَهُ مِنْ أَجْلِ الْعِلْمِ مُنْذُ أَنْ كَانَ صَغِيرًا", "segs": [{"ar": "زَوْجُكِ أَدْرَى بِمَا يُصْلِحُ لَهُ وَلَنَا فِي الدِّينِ وَالدُّنْيَا", "uz": "Ering din va dunyoda o'ziga va bizga nima yaxshi ekanini yaxshiroq biladi"}, {"ar": "وَأَنْتِ تَعْرِفِينَ أَنَّهُ نَذَرَ نَفْسَهُ مِنْ أَجْلِ الْعِلْمِ مُنْذُ أَنْ كَانَ صَغِيرًا", "uz": "sen bilasan, u kichikligidan beri o'zini ilmga bag'ishlagan"}], "full_uz": "Ering din va dunyoda o'ziga va bizga nima yaxshi ekanini yaxshiroq biladi — sen bilasan, u kichikligidan beri o'zini ilmga bag'ishlagan.", "note": null},
  {"num": 346, "time": "00:25:03,000 --> 00:25:12,619", "arabic": "جَزَاكِ اللَّهُ كُلَّ خَيْرٍ يَا أُمَّ، كُلَّمَا أَوْجَعَ سَفَرٌ قَلْبِي أَتَذَكَّرُ حَدِيثَكِ فَيَنْشَرِحُ صَدْرِي", "segs": null, "full_uz": "Alloh sizga har xil yaxshilikni bersin, onajon — safar yuragimni og'ritganda so'zingizni eslasam, ko'nglim yayraydi.", "note": null},
  {"num": 348, "time": "00:25:12,619 --> 00:25:20,299", "arabic": "طَلَبْتُ عَوْنَكِ يَا عَمَّتِي فَإِذَا بِكِ تَنْتَصِرِينَ لِمُحَمَّدٍ عَلَيَّ، لَيْتَنِي لَمْ أَفْعَلْ ذَلِكَ", "segs": null, "full_uz": "Sizdan yordam so'rovdim, ammaxon, mana endi Muhammadning tarafini olyapsiz. Koshki buni qilmasamiz edim.", "note": null},
  {"num": 350, "time": "00:25:20,299 --> 00:25:31,519", "arabic": "بَلْ أَنْتَصِرُ لِمَحَبَّةِ الشَّافِعِيِّ لِعِلْمِهِ يَا ابْنَتِي، وَلَنْ نَقِفَ عُثْرَةً فِي طَرِيقِهِ، أَفَهِمْتِ؟", "segs": null, "full_uz": "Yo'q, men ash-Shofi'iyning ilmga muhabbatini qo'llab-quvvatlayapman, qizim, va uning yo'liga to'siq bo'lmaymiz. Tushundingmi?", "note": null},
  {"num": 353, "time": "00:25:33,839 --> 00:25:42,479", "arabic": "كَيْفَ تَجِدُكَ فِي عَمَلِكَ يَا أَبَا اللَّيْثِ؟ أَشْعُرُ بِقَلِيلٍ مِنَ الْمَلَلِ", "segs": null, "full_uz": "Ishingda o'zingni qanday his qilyapsan, Abu al-Lays? Biroz zerikish his qilyapman.", "note": null},
  {"num": 355, "time": "00:25:42,479 --> 00:25:50,519", "arabic": "أَنْتَ مَلُولٌ يَا رَجُلُ، أَوَ تَجِدُ أَحْسَنَ مِنْ رِئَاسَةِ دِيوَانِ الْقَضَاءِ؟ مَتَى تَثْبُتُ فِي عَمَلٍ؟", "segs": null, "full_uz": "Sen zerikuvchi ekansan-a. Qozilik devoni raisligidan yaxshiroqni topasanmi? Qachon bir ishda barqaror bo'lasan?", "note": null},
  {"num": 358, "time": "00:25:50,519 --> 00:26:04,779", "arabic": "مَا دَامَ صَدِيقِي أَبُو الْجَحْجَاحِ فِي دِيوَانِ حَرَسِ أَمِيرِ الْمُؤْمِنِينَ، فَأَنَا أَنْتَقِي مِنَ الْوَظَائِفِ مَا أَشَاءُ، أَمْ إِنَّكَ مَلِلْتَ مِنَ التَّوَسُّطِ لِي؟", "segs": [{"ar": "مَا دَامَ صَدِيقِي أَبُو الْجَحْجَاحِ فِي دِيوَانِ حَرَسِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Do'stim Abu al-Jahjoh Amir al-Mo'minin soqchilari devonida ekan"}, {"ar": "فَأَنَا أَنْتَقِي مِنَ الْوَظَائِفِ مَا أَشَاءُ", "uz": "xohlagan lavozimni tanlayveraman"}, {"ar": "أَمْ إِنَّكَ مَلِلْتَ مِنَ التَّوَسُّطِ لِي؟", "uz": "yoki men uchun vositachilik qilishdan charchadingmi?"}], "full_uz": "Do'stim Abu al-Jahjoh Amir al-Mo'minin soqchilari devonida ekan, xohlagan lavozimni tanlayveraman — yoki men uchun vositachilik qilishdan charchadingmi?", "note": null},
  {"num": 361, "time": "00:26:04,779 --> 00:26:14,059", "arabic": "وَهَلْ مَا أَنَا فِيهِ مِنْ نِعْمَةٍ إِلَّا بِسَبَبِكَ يَا صَاحِبِي؟ أَنَسِيتَ أَنَّكَ أَنْتَ مَنْ أَلْحَقَنِي بِحَرَسِ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Men ega bo'lgan ne'mat sening sabab bo'lishingdan boshqa narsami, do'stim? Meni Amir al-Mo'minin soqchilariga qo'shgan sen ekaningni unutdingmi?", "note": null},
  {"num": 363, "time": "00:26:14,059 --> 00:26:19,819", "arabic": "دَعْنَا مِنْ هَذَا الْحَدِيثِ الْآنَ، وَقُلْ لِي مَا الْأَخْبَارُ؟ هَلْ عَادَ سَيِّدُكَ؟", "segs": null, "full_uz": "Hozir bu gapni qo'yib turaylik — ayt-chi, yangiliklar bormi? Xo'jayining qaytdimi?", "note": null},
  {"num": 366, "time": "00:26:20,519 --> 00:26:22,200", "arabic": "نَحْنُ نَتَرَقَّبُ وُصُولَهَا", "segs": null, "full_uz": "Biz uning kelishini kutmoqdamiz.", "note": null},
  {"num": 367, "time": "00:26:22,200 --> 00:26:41,799", "arabic": "تُرَى مَا الَّذِي تُخَبِّئُهُ لَنَا الْأَيَّامُ يَا أَبَا الْجَهْجَةِ؟ كُلُّ خَيْرٍ، وَمَا دَامَتِ الْأُمُورُ آلَتْ إِلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ وَمِنْ خَلْفِهِ أَبُو الْعَبَّاسِ", "segs": [{"ar": "تُرَى مَا الَّذِي تُخَبِّئُهُ لَنَا الْأَيَّامُ يَا أَبَا الْجَهْجَةِ؟", "uz": "Qiziq, kunlar bizga nima saqlab qo'ygan ekan, Abu al-Jahja?"}, {"ar": "كُلُّ خَيْرٍ", "uz": "Faqat yaxshilik"}, {"ar": "وَمَا دَامَتِ الْأُمُورُ آلَتْ إِلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ وَمِنْ خَلْفِهِ أَبُو الْعَبَّاسِ", "uz": "ishlar xo'jayinim Amir al-Mo'minin al-Amin va uning orqasida Abu al-Abbosga o'tgani uchun"}], "full_uz": "Qiziq, kunlar bizga nima saqlab qo'ygan ekan, Abu al-Jahja? Faqat yaxshilik — ishlar xo'jayinim Amir al-Mo'minin al-Amin va uning orqasida Abu al-Abbosga o'tgani uchun.", "note": null},
  {"num": 371, "time": "00:26:41,799 --> 00:27:19,519", "arabic": "فَنَحْنُ فِي النَّعِيمِ يَا أَبَا اللَّيْثِ، نَحْنُ فِي النَّعِيمِ", "segs": null, "full_uz": "Biz ne'matdamiz, Abu al-Lays, biz ne'matdamiz.", "note": null},
  {"num": 374, "time": "00:27:19,519 --> 00:27:33,500", "arabic": "وَيَبْأَسُ فِي خُرُوجِي إِلَى بَغْدَادَ", "segs": null, "full_uz": "Bag'dodga chiqishimda yomonlik ko'rasan.", "note": null},
  {"num": 375, "time": "00:27:33,500 --> 00:27:39,859", "arabic": "يَا مَوْلَايَ، إِنَّ خُرُوجَكَ إِلَى بَغْدَادَ الْآنَ خُطَّةٌ غَيْرُ مَحْسُوبَةِ الْعَوَاقِبِ", "segs": null, "full_uz": "Xo'jayinim, sizning hozir Bag'dodga chiqishingiz oqibati hisobga olinmagan reja.", "note": null},
  {"num": 378, "time": "00:27:39,859 --> 00:27:41,519", "arabic": "كَيْفَ؟", "segs": null, "full_uz": "Qanday qilib?", "note": null},
  {"num": 379, "time": "00:27:42,720 --> 00:27:49,840", "arabic": "اِعْلَمْ يَا مَوْلَايَ، لَوْ لَأَنَّ ابْنَ الرَّبِيعِ لَمْ يَكُنْ مُطْمَئِنًّا إِلَى رِضَا الْأَمِينِ بِفِعْلِ هَذَا لَمَا تَجَرَّأَ عَلَى الْقِيَامِ بِهِ", "segs": null, "full_uz": "Bilib qo'ying, xo'jayinim — agar Ibn ar-Rabi' al-Aminning bu ishga rozi ekaniga ishonch hosil qilmaganida, buni qilishga jur'at etmagan bo'lardi.", "note": null},
  {"num": 382, "time": "00:27:49,840 --> 00:27:57,940", "arabic": "نَعَمْ، أَخْشَى يَا مَوْلَايَ أَنَّ هُنَاكَ شَيْئًا مَا يُدَبَّرُ فِي الْخَفَاءِ", "segs": null, "full_uz": "Ha. Qo'rqamanki, xo'jayinim, yashirincha biror narsa rejalashtirilmoqda.", "note": null},
  {"num": 385, "time": "00:27:57,940 --> 00:28:07,740", "arabic": "أَبَا الْعَبَّاسِ، خَشْيَتُكَ هَذِهِ تُقْلِقُنِي", "segs": null, "full_uz": "Abu al-Abbos, bu qo'rquving meni tashvishga solmoqda.", "note": null},
  {"num": 387, "time": "00:28:07,740 --> 00:28:16,560", "arabic": "مَاذَا هُنَاكَ؟ يَا مَوْلَايَ، نَحْنُ هُنَا بَيْنَ أَنْصَارِنَا وَجُنُودِنَا", "segs": null, "full_uz": "Nima gap o'zi? Xo'jayinim, biz bu yerda o'z tarafdorlarimiz va askarlarimiz orasidamiz.", "note": null},
  {"num": 391, "time": "00:28:16,559 --> 00:28:25,980", "arabic": "أَمَّا إِذَا عُدْنَا إِلَى بَغْدَادَ فَنَحْنُ هُنَاكَ قِلَّةٌ، أَمَّا هُنَا فَنَحْنُ فِي مَنْعَةٍ بَيْنَ رِجَالِنَا وَأَنْصَارِنَا", "segs": null, "full_uz": "Bag'dodga qaytsak, u yerda ozchilikmiz — bu yerda esa o'z odamlarimiz va tarafdorlarimiz orasida himoyalanganmiz.", "note": null},
  {"num": 393, "time": "00:28:25,980 --> 00:28:31,339", "arabic": "وَلَكِنْ ذَلِكَ لَنْ يَمُرَّ عَلَى أَخِي الْأَمِينِ، هُوَ رُبَّمَا أَثَارَ حَفِيظَتَهُ", "segs": null, "full_uz": "Ammo bu akam al-Aminga bekor o'tmaydi — balki uning g'azabini qo'zg'atadi.", "note": null},
  {"num": 395, "time": "00:28:31,339 --> 00:28:42,659", "arabic": "إِذَنْ لِنَنْتَظِرْ مَا يَكُونُ مِنْ أَمِيرِ الْمُؤْمِنِينَ، فَإِنْ تَبَيَّنَ لَنَا عَزْمُهُ عَلَى إِمْضَاءِ عُهُودِ أَبِيكَ رَحِمَهُ اللَّهُ خَرَجْنَا إِلَى بَغْدَادَ", "segs": [{"ar": "إِذَنْ لِنَنْتَظِرْ مَا يَكُونُ مِنْ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Unda Amir al-Mo'minindan nima bo'lishini kutaylik"}, {"ar": "فَإِنْ تَبَيَّنَ لَنَا عَزْمُهُ عَلَى إِمْضَاءِ عُهُودِ أَبِيكَ رَحِمَهُ اللَّهُ", "uz": "agar otangizning — Alloh unga rahmat qilsin — ahdlarini bajarishga qat'iy niyati oydinlashsa"}, {"ar": "خَرَجْنَا إِلَى بَغْدَادَ", "uz": "Bag'dodga chiqamiz"}], "full_uz": "Unda Amir al-Mo'minindan nima bo'lishini kutaylik — agar otangizning — Alloh unga rahmat qilsin — ahdlarini bajarishga qat'iy niyati oydinlashsa, Bag'dodga chiqamiz.", "note": null},
  {"num": 398, "time": "00:28:42,660 --> 00:28:51,060", "arabic": "وَإِنْ لَمْ يَكُنِ الْأَمْرُ كَذَلِكَ مَكَثْنَا فِي خُرَاسَانَ، فَنَتَدَبَّرُ الْأُمُورَ وَنُفَكِّرُ فِي مَآلَاتِهَا", "segs": null, "full_uz": "Agar unday bo'lmasa, Xurosonda qolamiz — ishlarni chuqur o'ylab, oqibatlarini fikrlaymiz.", "note": null},
  {"num": 401, "time": "00:28:51,060 --> 00:29:00,540", "arabic": "وَنَحْنُ هُنَا عَلَى طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ مَا كَانَ طَائِعًا لِلَّهِ وَلِأَبِيهِ، وَإِلَّا لَا طَاعَةَ لَهُ عَلَيْنَا", "segs": null, "full_uz": "Biz bu yerda Amir al-Mo'mininga, u Allohga va otasiga itoatkor bo'lgani muddatda itoat qilamiz — aks holda, unga itoatimiz yo'q.", "note": null},
  {"num": 404, "time": "00:29:12,660 --> 00:29:23,820", "arabic": "فَمَاذَا تَرَى يَا أَبَا الْعَبَّاسِ؟", "segs": null, "full_uz": "Nima deysan, Abu al-Abbos?", "note": null},
  {"num": 405, "time": "00:29:23,820 --> 00:29:31,980", "arabic": "أَرَى يَا أَمِيرَ الْمُؤْمِنِينَ أَنْ تُرْسِلَ إِلَى الْأَمِيرِ الْمَأْمُونِ وَتَطْلُبَ إِلَيْهِ الْعَوْدَةَ سَرِيعًا إِلَى بَغْدَادَ", "segs": null, "full_uz": "Menimcha, Amir al-Mo'minin, Amir al-Ma'munga xat yuborib, tezda Bag'dodga qaytishini talab qilishingiz kerak.", "note": null},
  {"num": 407, "time": "00:29:31,980 --> 00:29:38,640", "arabic": "إِنَّ مُكُوثَهُ هُنَاكَ وَسَطَ الْمُغْرِضِينَ وَالْحَاقِدِينَ لَا يَحْمِلُ أَيَّ خَيْرٍ", "segs": null, "full_uz": "Uning g'arazgo'ylar va hasadgo'ylar orasida qolishida hech qanday yaxshilik yo'q.", "note": null},
  {"num": 408, "time": "00:29:38,640 --> 00:29:48,860", "arabic": "أَبِقَصْدِ ابْنِ سَهْلٍ؟ نَعَمْ، ابْنِ سَهْلٍ", "segs": null, "full_uz": "Ibn Sahlni nazarda tutyapsanmi? Ha, Ibn Sahlni.", "note": null},
  {"num": 410, "time": "00:29:48,860 --> 00:29:59,100", "arabic": "وَأَمْثَالُهُ كُثُرٌ مِنَ الْحَاقِدِينَ الَّذِينَ تَدَثَّرُوا بِعَبَاءَةِ الْإِسْلَامِ لِيَسْهُلَ عَلَيْهِمْ بَثُّ أَحْقَادِهِمْ وَنَشْرُ الْفَوْضَى فِي دِيَارِ الْمُسْلِمِينَ", "segs": null, "full_uz": "Uning kabilari islom to'nini yopingan hasadgo'ylar ko'p — bu ularga o'z kinalarini tarqatib, musulmonlar diyorida tartibsizlik yoyishni osonlashtiradi.", "note": null},
  {"num": 412, "time": "00:29:59,099 --> 00:30:08,959", "arabic": "إِنَّ أَخِي الْمَأْمُونَ أَعْقَلُ مِنْ أَنْ تَمُرَّ عَلَيْهِ وَشْيَاتُهُمْ", "segs": null, "full_uz": "Ukam al-Ma'mun ularning tuhmatlari o'tib ketishi uchun aqldan ortiqroqdir.", "note": null},
  {"num": 413, "time": "00:30:08,959 --> 00:30:15,559", "arabic": "لَا تَأْمَنْ غَدْرَ هَؤُلَاءِ يَا مَوْلَايَ، فَكَمْ كَادُوا لِأَبِيكَ مِنْ قَبْلُ", "segs": null, "full_uz": "Bularning xiyonatidan xotirjam bo'lmang, xo'jayinim — ilgari otangizga qancha fitna qilishgan edi.", "note": null},
  {"num": 415, "time": "00:30:15,559 --> 00:32:16,039", "arabic": "شَهْوَةُ الْحُبِّ تُفْسِدُ الرِّجَالَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Muhabbat shahvati erkaklarni buzadi, ey Amir al-Mo'minin.", "note": null},
  {"num": 420, "time": "00:32:16,039 --> 00:32:25,719", "arabic": "عُمَيْرُ، عُمَيْرُ، أَحْضِرْ لِي مَاءً فَقَدْ نَالَ مِنِّي الْعَطَشُ", "segs": null, "full_uz": "Umayr, Umayr! Menga suv keltir, chanqoq meni bezovta qilyapti.", "note": null},
  {"num": 422, "time": "00:32:29,099 --> 00:32:33,099", "arabic": "لِمَاذَا لَا تَأْتِي إِلَى جَدَّتِكَ يَا وَلَدُ؟", "segs": null, "full_uz": "Nega buvingga kelmaysan, bolam?", "note": null},
  {"num": 423, "time": "00:32:34,099 --> 00:32:40,099", "arabic": "عُمَيْرٌ لَيْسَ مَوْجُودًا، لَقَدْ ذَهَبَ إِلَى حَلْقَةِ الدَّرْسِ وَأَظُنُّهُ وَدَّعَكِ قَبْلَ أَنْ يَذْهَبَ", "segs": null, "full_uz": "Umayr yo'q — dars halqasiga ketdi, o'ylashimcha, ketishdan oldin sizga xayrlashib ham o'tgan.", "note": null},
  {"num": 425, "time": "00:32:40,099 --> 00:32:44,099", "arabic": "فَلِمَاذَا تُنَادِيهِ؟ نَسِيتُ", "segs": null, "full_uz": "Unda nega uni chaqiryapsiz? Unutibman.", "note": null},
  {"num": 427, "time": "00:32:44,099 --> 00:32:54,099", "arabic": "وَبِمَا أَنَّهُ قَدْ خَرَجَ فَلَيْسَ لِي إِلَّا أَنْتِ أَيَّتُهَا الْـ... أَحْضِرِي لِي مَاءً", "segs": null, "full_uz": "U chiqib ketgan ekan, senda... boshqa hech kimim yo'q. Menga suv keltir.", "note": null},
  {"num": 429, "time": "00:32:54,099 --> 00:33:03,519", "arabic": "وَلَا تَنْسَيْ وَأَنْتِ تُحْضِرِينَ الْمَاءَ أَنْ تُحْضِرِي الطَّعَامَ، حَاضِرٌ حَاضِرٌ حَاضِرٌ، وَهَلْ تُرِيدِينَ شَيْئًا آخَرَ؟", "segs": [{"ar": "وَلَا تَنْسَيْ وَأَنْتِ تُحْضِرِينَ الْمَاءَ أَنْ تُحْضِرِي الطَّعَامَ", "uz": "Suv keltirayotganingda ovqat keltirishni ham unutma"}, {"ar": "حَاضِرٌ حَاضِرٌ حَاضِرٌ", "uz": "Xo'p, xo'p, xo'p"}, {"ar": "وَهَلْ تُرِيدِينَ شَيْئًا آخَرَ؟", "uz": "Yana biror narsa kerakmi?"}], "full_uz": "Suv keltirayotganingda ovqat keltirishni ham unutma. Xo'p, xo'p, xo'p — yana biror narsa kerakmi?", "note": null},
  {"num": 431, "time": "00:33:03,519 --> 00:33:15,980", "arabic": "حِينَ أَحْتَاجُ إِلَيْكِ أُنَادِيكِ، يَا رَبِّ مَا الَّذِي فَعَلْتُهُ لِتَجْعَلَنِي خَادِمَةً لِهَذِهِ الْعَجُوزِ طُولَ هَذِهِ السِّنِينَ؟", "segs": [{"ar": "حِينَ أَحْتَاجُ إِلَيْكِ أُنَادِيكِ", "uz": "Senga muhtoj bo'lganimda chaqiraman"}, {"ar": "يَا رَبِّ مَا الَّذِي فَعَلْتُهُ لِتَجْعَلَنِي خَادِمَةً لِهَذِهِ الْعَجُوزِ طُولَ هَذِهِ السِّنِينَ؟", "uz": "Yo Rabbim, men nima qilgan edimki, meni shu qariyaga shuncha yillar xizmatkor qilib qo'yding?"}], "full_uz": "Senga muhtoj bo'lganimda chaqiraman. Yo Rabbim, men nima qilgan edimki, meni shu qariyaga shuncha yillar xizmatkor qilib qo'yding?", "note": null},
  {"num": 433, "time": "00:33:15,980 --> 00:33:27,219", "arabic": "مُنْذُ أَنْ أُصِيبَتْ بِالْعَمَى لَا تَحْفَظُ إِلَّا اسْمِي وَلَا تَكُفُّ عَنِ الطَّلَبِ، خُذِي هَذَا وَلَا تَأْخُذِي ذَاكَ، اِفْعَلِي هَذَا وَلَا تَفْعَلِي ذَاكَ", "segs": [{"ar": "مُنْذُ أَنْ أُصِيبَتْ بِالْعَمَى لَا تَحْفَظُ إِلَّا اسْمِي وَلَا تَكُفُّ عَنِ الطَّلَبِ", "uz": "Ko'zi ojiz bo'lganidan beri faqat ismimni yodda tutadi va talabini to'xtatmaydi"}, {"ar": "خُذِي هَذَا وَلَا تَأْخُذِي ذَاكَ", "uz": "buni ol, uni olma"}, {"ar": "اِفْعَلِي هَذَا وَلَا تَفْعَلِي ذَاكَ", "uz": "buni qil, uni qilma"}], "full_uz": "Ko'zi ojiz bo'lganidan beri faqat ismimni yodda tutadi va talabini to'xtatmaydi — buni ol, uni olma, buni qil, uni qilma.", "note": null},
  {"num": 436, "time": "00:33:27,220 --> 00:33:33,900", "arabic": "يَا رَبِّ لَقَدْ دَعَوْتُ إِلَى صَبْرِي يَا رَبِّ، بِمَ تَتَمْتِمِينَ؟", "segs": null, "full_uz": "Yo Rabbim, sabrimga sig'inaman. Nima deb pichirlayapsan?", "note": null},
  {"num": 438, "time": "00:33:33,900 --> 00:33:46,880", "arabic": "أَعْرِفُ أَنَّكِ تَتَذَمَّرِينَ مِنِّي وَمِنْ حَاجَتِي، لَوْلَا بُكَاؤُهُ الْمُسْتَمِرُّ لَمَا آلَ إِلَيْهِ حَالُ وَلَدِي مُنْذُ تَزَوَّجَكِ", "segs": null, "full_uz": "Bilaman, mendan va hojatimdan norozisan — o'sha (bola) doimiy yig'lamaganida, o'g'lim seni uylanganidan beri bunday holga tushmagan bo'lardi.", "note": null},
  {"num": 441, "time": "00:33:46,880 --> 00:33:53,799", "arabic": "لَمَا فَقَدْتُ بَصَرِي وَلَمَا احْتَجْتُكِ فِي شَيْءٍ، أَيَّتُهَا...", "segs": null, "full_uz": "Ko'zim ham ko'r bo'lmasdi, senga hech narsada muhtoj ham bo'lmasdim, ey...", "note": null},
  {"num": 444, "time": "00:33:53,799 --> 00:34:04,740", "arabic": "لَكِنْ مَاذَا فَعَلَ؟ إِنَّهُ قَضَاءُ اللَّهِ وَقَدَرُهُ، إِنَّهُ قَضَاءُ اللَّهِ وَقَدَرُهُ", "segs": null, "full_uz": "Lekin u nima qilibdi? Bu Allohning qazo va qadaridir. Bu Allohning qazo va qadaridir.", "note": null},
  {"num": 447, "time": "00:34:04,740 --> 00:34:13,519", "arabic": "كُلُّ مَا أَدْعُو اللَّهَ بِهِ أَنْ يَقْبِضَنِي إِلَيْهِ لِأَرْتَاحَ وَتَخْلُوَ لَكِ الْحَيَاةُ مَعَ وَلَدِكِ الْمَصُونِ، رَبِّي حَقِّقْ لَهَا مَا طَلَبَتْ", "segs": [{"ar": "كُلُّ مَا أَدْعُو اللَّهَ بِهِ أَنْ يَقْبِضَنِي إِلَيْهِ لِأَرْتَاحَ", "uz": "Yagona iltijoyim — Alloh meni O'ziga olib, rohat topishim"}, {"ar": "وَتَخْلُوَ لَكِ الْحَيَاةُ مَعَ وَلَدِكِ الْمَصُونِ", "uz": "va hayot seni asrаlgan o'g'ling bilan qolishi"}, {"ar": "رَبِّي حَقِّقْ لَهَا مَا طَلَبَتْ", "uz": "Robbim, unga so'ragan narsasini ato et"}], "full_uz": "Yagona iltijoyim — Alloh meni O'ziga olib, rohat topishim va hayot seni asrаlgan o'g'ling bilan qolishi. Robbim, unga so'ragan narsasini ato et.", "note": null},
  {"num": 450, "time": "00:34:13,519 --> 00:34:21,719", "arabic": "أَحْضِرْ لِي مَاءً بَارِدًا وَطَعَامًا سَاخِنًا، أَيُّهَا الْقَمِيئَةُ الْقَبِيحَةُ", "segs": null, "full_uz": "Menga sovuq suv va issiq ovqat keltir, ey badbashara xunuk!", "note": null},
  {"num": 452, "time": "00:34:21,719 --> 00:34:40,159", "arabic": "خَيْرًا يَا أَبَا مُعَاذٍ، مَا الْأَمْرُ الَّذِي أَرَدْتَ مِنْ أَجْلِهِ لِاخْتِلَاءٍ بِأَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xayr bo'lsin, Abu Muoz — Amir al-Mo'minin bilan yolg'iz uchrashishni istagan masalang nima edi?", "note": null},
  {"num": 455, "time": "00:34:40,159 --> 00:34:51,079", "arabic": "اَلْحَقُّ يَا مَوْلَايَ أَنَّهُ رَجَاءٌ يَتَّسِعُ كَرَمُ أَمِيرِ الْمُؤْمِنِينَ لَهُ، وَقَدْ تَرَدَّدْتُ غَيْرَ مَرَّةٍ فِي عَرْضِهِ عَلَيْكَ", "segs": null, "full_uz": "Haqiqatan ham, xo'jayinim, bu — Amir al-Mo'mininning saxovati keng bo'lgan bir iltimos, va men buni sizga aytishda necha marta ikkilangan edim.", "note": null},
  {"num": 461, "time": "00:34:51,079 --> 00:35:01,199", "arabic": "تَفَضَّلْ، قُلْ مَا عِنْدَكَ يَا ابْنَ الْأَشْعَثِ، أَعَزَّكَ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Marhamat, gapingni ayt, Ibn al-Ash'as. Alloh sizni aziz qilsin, Amir al-Mo'minin.", "note": null},
  {"num": 464, "time": "00:35:01,199 --> 00:35:11,400", "arabic": "إِنَّ الْعَفْوَ مِنْ شِيَمِ الْكِرَامِ، وَأَنْتَ سَلِيلُ أُسْرَةٍ عُرِفَتْ فِي الْآفَاقِ بِالْعَفْوِ وَالْكَرَمِ، رَحِمَ اللَّهُ أَبَاكَ الرَّشِيدَ", "segs": [{"ar": "إِنَّ الْعَفْوَ مِنْ شِيَمِ الْكِرَامِ", "uz": "Afv — mard kishilarning xislatidir"}, {"ar": "وَأَنْتَ سَلِيلُ أُسْرَةٍ عُرِفَتْ فِي الْآفَاقِ بِالْعَفْوِ وَالْكَرَمِ", "uz": "siz esa afv va saxovat bilan olamda tanilgan oiladan bo'lgan avlodsiz"}, {"ar": "رَحِمَ اللَّهُ أَبَاكَ الرَّشِيدَ", "uz": "Alloh otangiz ar-Rashidga rahmat qilsin"}], "full_uz": "Afv — mard kishilarning xislatidir, siz esa afv va saxovat bilan olamda tanilgan oiladan bo'lgan avlodsiz. Alloh otangiz ar-Rashidga rahmat qilsin.", "note": null},
  {"num": 467, "time": "00:35:11,400 --> 00:35:20,199", "arabic": "إِلَى جَدِّكَ الْعَبَّاسِ رَضِيَ اللَّهُ عَنْهُ، رَضِيَ اللَّهُ عَنْهُ وَعَنْ صَحَابَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Bobongiz al-Abbosgacha — Alloh undan rozi bo'lsin, Alloh undan va Rasululloh sollallohu alayhi va sallamning sahobalaridan rozi bo'lsin.", "note": null},
  {"num": 469, "time": "00:35:20,199 --> 00:35:38,079", "arabic": "وَبَعْدُ يَا مَوْلَايَ، فَرَجَائِي أَنْ يَشْمَلَ عَفْوُكَ خَادِمَكَ الشَّيْخَ بِشْرًا الْمَرِيسِيَّ، فَقَدْ كَفَاهُ مَا حَلَّ بِهِ فِيمَا مَضَى مِنَ السِّنِينَ مِنْ مُطَارَدَةٍ وَاخْتِفَاءٍ", "segs": [{"ar": "وَبَعْدُ يَا مَوْلَايَ، فَرَجَائِي أَنْ يَشْمَلَ عَفْوُكَ خَادِمَكَ الشَّيْخَ بِشْرًا الْمَرِيسِيَّ", "uz": "So'ng, xo'jayinim, umidim shuki, afvingiz xizmatkoringiz shayx Bishr al-Marisiyni ham qamrab olsin"}, {"ar": "فَقَدْ كَفَاهُ مَا حَلَّ بِهِ فِيمَا مَضَى مِنَ السِّنِينَ مِنْ مُطَارَدَةٍ وَاخْتِفَاءٍ", "uz": "o'tgan yillar davomida boshiga tushgan ta'qib va yashirinishlar unga yetarli bo'lgan"}], "full_uz": "So'ng, xo'jayinim, umidim shuki, afvingiz xizmatkoringiz shayx Bishr al-Marisiyni ham qamrab olsin — o'tgan yillar davomida boshiga tushgan ta'qib va yashirinishlar unga yetarli bo'lgan.", "note": null},
  {"num": 471, "time": "00:35:38,079 --> 00:35:56,119", "arabic": "لَوْ غَيْرُكَ تَشَفَّعَ عِنْدِي فِي بِشْرٍ الْمَرِيسِيِّ هَذَا يَا أَبَا مُعَاذٍ لَلَاقَى مَا تَتَنَدَّرُ بِهِ النَّاسُ", "segs": null, "full_uz": "Sendan boshqasi menga bu Bishr al-Marisiy haqida shafoat qilganida, odamlar hazil-mazax qiladigan narsaga uchragan bo'lardi, Abu Muoz.", "note": null},
  {"num": 473, "time": "00:35:56,119 --> 00:36:10,159", "arabic": "كَيْفَ تَتَشَفَّعُ فِي رَجُلٍ تَجَرَّأَ عَلَى اللَّهِ تَعَالَى وَكِتَابِهِ الْكَرِيمِ؟", "segs": null, "full_uz": "Alloh taolo va Uning karimi kitobiga jur'at qilgan bir kishi haqida qanday shafoat qilasan?", "note": null},
  {"num": 474, "time": "00:36:10,159 --> 00:36:14,119", "arabic": "أَعْرِفُ يَا مَوْلَايَ وَلَكِنْ أَنَا لَمْ أُكْمِلْ كَلَامِي بَعْدُ يَا ابْنَ الْأَشْرَسِ", "segs": null, "full_uz": "Bilaman, xo'jayinim. Ammo men gapimni hali tugatmadim, Ibn al-Ashras.", "note": null},
  {"num": 476, "time": "00:36:14,119 --> 00:36:24,460", "arabic": "اِغْفِرْ لِي زَلَّتِي يَا مَوْلَايَ، إِنَّمَا يُشَيِّعُهُ أَمْثَالُ بِشْرٍ هَذَا", "segs": null, "full_uz": "Xatoyimni kechiring, xo'jayinim. Uni faqat shu Bishr kabilar kuzatib boradi.", "note": null},
  {"num": 478, "time": "00:36:24,460 --> 00:36:34,579", "arabic": "لَعَلَّكَ تَعْرِفُ الْكَثِيرَ مِنْهُمْ كَمَا أَظُنُّ، مَنْ بَدَّعَ بَيْنَ النَّاسِ لَحَرِيٌّ بِالسَّيْفِ أَنْ يُبَاشِرَ عَمَلَهُ فِي أَعْنَاقِهِ", "segs": null, "full_uz": "Shekilli, ulardan ko'pini bilasan, deb o'ylayman. Odamlar orasida bid'at chiqargan kishining bo'ynida qilich o'z ishini boshlashga loyiqdir.", "note": null},
  {"num": 480, "time": "00:36:34,579 --> 00:36:44,280", "arabic": "وَالَّذِي نَفْسِي بِيَدِهِ، إِنْ ظَفِرْتُ بِشَيْخِ السُّوءِ هَذَا لَأَجْعَلَنَّهُ عِبْرَةً تَسْطُرُهَا أَوْرَاقُ التَّارِيخِ", "segs": null, "full_uz": "Jonim qo'lida bo'lgan Zotga qasamki, agar bu yovuz shayxni qo'lga tushirsam, tarix varaqlari yozadigan ibratga aylantiraman.", "note": null},
  {"num": 483, "time": "00:36:44,280 --> 00:37:00,500", "arabic": "وَإِنْ كَانَ الرَّشِيدُ رَحِمَهُ اللَّهُ تَجَاوَزَ عَنْ بَعْضِهِمْ تَقَرُّبًا إِلَى اللَّهِ بِالْعَفْوِ عَنْهُمْ، فَأَنَا سَأَتَقَرَّبُ إِلَى اللَّهِ بِقَطْعِ رِقَابِهِمْ", "segs": [{"ar": "وَإِنْ كَانَ الرَّشِيدُ رَحِمَهُ اللَّهُ تَجَاوَزَ عَنْ بَعْضِهِمْ تَقَرُّبًا إِلَى اللَّهِ بِالْعَفْوِ عَنْهُمْ", "uz": "Agar ar-Rashid — Alloh unga rahmat qilsin — ba'zilarini afv qilib, Allohga yaqinlashgan bo'lsa"}, {"ar": "فَأَنَا سَأَتَقَرَّبُ إِلَى اللَّهِ بِقَطْعِ رِقَابِهِمْ", "uz": "men ularning bo'ynini kesish bilan Allohga yaqinlashaman"}], "full_uz": "Agar ar-Rashid — Alloh unga rahmat qilsin — ba'zilarini afv qilib, Allohga yaqinlashgan bo'lsa, men ularning bo'ynini kesish bilan Allohga yaqinlashaman.", "note": null},
  {"num": 487, "time": "00:37:00,500 --> 00:37:19,579", "arabic": "بِإِذْنِ اللَّهِ", "segs": null, "full_uz": "Alloh izni bilan.", "note": null},
  {"num": 489, "time": "00:37:19,579 --> 00:37:24,179", "arabic": "أَجَلْ يَا أُمَّهْ", "segs": null, "full_uz": "Ha, onajon.", "note": null},
  {"num": 490, "time": "00:37:24,179 --> 00:37:30,880", "arabic": "تُوُفِّيَ ابْنُ أَحَدِ الْجِيرَانِ وَيَجِبُ أَنْ أَخْرُجَ فِي جِنَازَتِهِ، مَنِ الْمُتَوَفَّى؟", "segs": null, "full_uz": "Qo'shnilardan birining o'g'li vafot etdi, uning janozasiga chiqishim kerak. Kim vafot etdi?", "note": null},
  {"num": 492, "time": "00:37:30,880 --> 00:37:36,500", "arabic": "اِبْنُ أَبِي سَرْحَانَ، لَعَلَّكِ تَعْرِفِينَهُ، إِنَّ لَهُ دُكَّانًا قَرِيبًا مِنْ دُكَّانِنَا فِي السُّوقِ، عَرَفْتُهُ", "segs": null, "full_uz": "Abu Sarhonning o'g'li — balki tanirsiz, bozorda do'konimizga yaqin bir do'koni bor. Tanidim.", "note": null},
  {"num": 495, "time": "00:37:36,500 --> 00:37:42,199", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، رَحِمَ اللَّهُ وَلَدًا، مَتَى تُوُفِّيَ؟", "segs": null, "full_uz": "La havla va la quvvata illa billah. Alloh o'g'longa rahmat qilsin. Qachon vafot etdi?", "note": null},
  {"num": 497, "time": "00:37:42,199 --> 00:37:47,840", "arabic": "هَذَا الصَّبَاحَ، إِنَّ لِلَّهِ وَإِنَّ إِلَيْهِ رَاجِعُونَ، وَدِّعْنِي يَا أُمَّهْ", "segs": null, "full_uz": "Bugun ertalab. Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz. Meni yo'lga soling, onajon.", "note": null},
  {"num": 500, "time": "00:37:47,840 --> 00:37:54,440", "arabic": "بِأَمَانِ اللَّهِ يَا وَلَدِي، أَتُرِيدِينَ شَيْئًا نُحْضِرُهُ مِنَ السُّوقِ عِنْدَ عَوْدَتِي؟", "segs": null, "full_uz": "Alloh amonatida bo'l, o'g'lim. Qaytishimda bozordan biror narsa keltiraymi?", "note": null},
  {"num": 502, "time": "00:37:54,440 --> 00:38:11,380", "arabic": "لَا جَزَاكَ اللَّهُ خَيْرًا، اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ بِأَمَانِ اللَّهِ", "segs": null, "full_uz": "Yo'q, Alloh senga yaxshilik bersin. Assalomu alaykum. Va alaykum assalom va rahmatulloh, Alloh amonatida bo'l.", "note": null},
  {"num": 506, "time": "00:38:11,380 --> 00:38:16,860", "arabic": "اَلسَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Xo'jayinim Amir al-Mo'minin va uning hamrohlariga salom bo'lsin. Va alaykum assalom va rahmatulloh.", "note": null},
  {"num": 508, "time": "00:38:16,860 --> 00:38:27,460", "arabic": "اِجْلِسْ يَا ابْنَ الرَّبِيعِ، هَلْ أَنْزَلْتُمُ ابْنَ عَمِّ أَمِيرِ الْمُؤْمِنِينَ مَكَانًا يَلِيقُ بِهِ؟", "segs": null, "full_uz": "O'tir, Ibn ar-Rabi'. Amir al-Mo'mininning amakivachchasini munosib joyga joylashtirdingizmi?", "note": null},
  {"num": 510, "time": "00:38:27,460 --> 00:38:36,400", "arabic": "لَوْ لَمْ يَكُنِ الشَّافِعِيُّ ابْنَ عَمِّ أَمِيرِ الْمُؤْمِنِينَ لَكُنَّا أَنْزَلْنَاهُ فِي عُيُونِنَا، فَكَيْفَ وَهُوَ ابْنُ عَمِّ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": [{"ar": "لَوْ لَمْ يَكُنِ الشَّافِعِيُّ ابْنَ عَمِّ أَمِيرِ الْمُؤْمِنِينَ لَكُنَّا أَنْزَلْنَاهُ فِي عُيُونِنَا", "uz": "Agar ash-Shofi'iy Amir al-Mo'mininning amakivachchasi bo'lmaganida ham, uni ko'zimiz ustiga joylashtirar edik"}, {"ar": "فَكَيْفَ وَهُوَ ابْنُ عَمِّ أَمِيرِ الْمُؤْمِنِينَ؟", "uz": "u amakivachchasi bo'lsa, qandoq bo'lmasin?"}], "full_uz": "Agar ash-Shofi'iy Amir al-Mo'mininning amakivachchasi bo'lmaganida ham, uni ko'zimiz ustiga joylashtirar edik — u amakivachchasi bo'lsa, qandoq bo'lmasin?", "note": "أَنْزَلَهُ فِي عَيْنِهِ — kimnidir juda hurmat-e'zoz bilan qarshi olish, majoziy ibora."},
  {"num": 513, "time": "00:38:36,400 --> 00:38:43,539", "arabic": "بَارَكَ اللَّهُ فِيكَ، بَارَكَ اللَّهُ فِيكَ يَا أَبَا الْعَبَّاسِ، إِنَّهُ رَجُلٌ نَدَرَ أَنْ تَجِدَ مِثِيلَهُ يَا أَبَا مُوسَى", "segs": null, "full_uz": "Alloh senga barakot bersin. Alloh senga barakot bersin, Abu al-Abbos — u shunday kishiki, tengini topish qiyin, Abu Muso.", "note": null},
  {"num": 516, "time": "00:38:43,539 --> 00:38:53,259", "arabic": "وَهُوَ وَلَا أُزَكِّيهِ عَلَى اللَّهِ تَعَالَى، كَنْزٌ مِنْ كُنُوزِ دَوْلَتِكَ، وَهُوَ كَالشَّمْسِ تُشْرِقُ مِنْ جَمِيعِ جِهَاتِهَا", "segs": null, "full_uz": "Uni Alloh oldida poklamayman, lekin u — davlatingizning xazinalaridan biri, u barcha tomonlaridan yorug'lik sочadigan quyosh kabidir.", "note": "لَا أُزَكِّيهِ عَلَى اللَّهِ — kimnidir maqtaganda ishlatiladigan tavoze ibora, «uni Allohdan yaxshiroq bilmayman» ma'nosida."},
  {"num": 519, "time": "00:38:53,259 --> 00:39:01,360", "arabic": "مَا دَامَ فِي دَوْلَةِ الْإِسْلَامِ كَالشَّافِعِيِّ وَأَمْثَالِهِ فَهِيَ بِأَلْفِ خَيْرٍ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Islom davlatida ash-Shofi'iy va uning kabilar bo'lar ekan, u ming yaxshilikda bo'ladi, Ibn ar-Rabi'.", "note": null},
  {"num": 521, "time": "00:39:01,360 --> 00:39:11,179", "arabic": "أَهْلًا بِكَ يَا أَبَا عَبْدِ اللَّهِ، قَدْ أَضَاءَتْ بَغْدَادُ بِقُدُومِكَ، بَغْدَادُ مُضَاءَةٌ بِأَمْثَالِكَ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Xush kelibsiz, Abu Abdulloh — Bag'dod sizning kelishingiz bilan yorishdi. Bag'dod sizga o'xshaganlar bilan yorishadi, Ibn Hanbal.", "note": null},
  {"num": 524, "time": "00:39:11,179 --> 00:39:18,040", "arabic": "بَرَّكَ اللَّهُ بِكَ يَا شَيْخَنَا، مَا إِنْ سَمِعْتُ بِقُدُومِكَ إِلَى بَغْدَادَ حَتَّى سَارَعْتُ بِالسُّؤَالِ عَنْ مَكَانِ إِقَامَتِي", "segs": null, "full_uz": "Alloh sizga barakot bersin, shayximiz — Bag'dodga kelganingizni eshitishim bilanoq, turgan joyingizni so'rashga shoshildim.", "note": null},
  {"num": 527, "time": "00:39:18,040 --> 00:39:29,540", "arabic": "وَكُنْتُ ذَاهِبًا لِأَرَاكَ، هَا هَلْ لَوْ تَعْلَمُ كَمْ أَنَا فِي شَوْقٍ لِمُجَالَسَتِكَ وَالْحَدِيثِ مَعَكَ، هَيَّا بِنَا نُكْمِلُ طَرِيقَنَا إِلَى دَارِي، عَلَى بَرَكَةِ اللَّهِ", "segs": [{"ar": "وَكُنْتُ ذَاهِبًا لِأَرَاكَ", "uz": "Va sizni ko'rgani ketayotgan edim"}, {"ar": "هَا هَلْ لَوْ تَعْلَمُ كَمْ أَنَا فِي شَوْقٍ لِمُجَالَسَتِكَ وَالْحَدِيثِ مَعَكَ", "uz": "Bilsangiz edi, sizning suhbatingizga va gaplashishga qanchalik ishtiyoqmandman!"}, {"ar": "هَيَّا بِنَا نُكْمِلُ طَرِيقَنَا إِلَى دَارِي، عَلَى بَرَكَةِ اللَّهِ", "uz": "Yuring, uyimga yo'limizni davom ettiraylik. Alloh barakasi bilan"}], "full_uz": "Va sizni ko'rgani ketayotgan edim. Bilsangiz edi, sizning suhbatingizga va gaplashishga qanchalik ishtiyoqmandman! Yuring, uyimga yo'limizni davom ettiraylik. Alloh barakasi bilan.", "note": null},
  {"num": 531, "time": "00:39:29,539 --> 00:39:47,779", "arabic": "إِلَهِي وَسَيِّدِي، كَمَا زَيَّنْتَ السَّمَاءَ بِالنُّجُومِ وَالْكَوَاكِبِ", "segs": null, "full_uz": "Ilohim va sayyidim, samoni yulduzlar va sayyoralar bilan bezaganingdek.", "note": null},
  {"num": 533, "time": "00:39:47,779 --> 00:39:57,579", "arabic": "زَيِّنِ الْأَرْضَ بِعُلَمَاءَ رَبَّانِيِّينَ لَا يَخْشَوْنَ إِلَّاكَ، يَا مُغِيثُ أَغِثْنَا", "segs": null, "full_uz": "Yerni Sendan boshqa hech kimdan qo'rqmaydigan robboniy olimlar bilan bezagin — ey Mug'is, bizga madad ber.", "note": null},
  {"num": 536, "time": "00:39:57,579 --> 00:40:10,319", "arabic": "أَنْتَ الْقَوِيُّ الْقَادِرُ عَلَى كُلِّ شَيْءٍ يَا اللَّهُ، أَهْلًا بِكَ يَا ابْنَ حَنْبَلٍ زِيَارَةٌ مُبَارَكَةٌ", "segs": null, "full_uz": "Sen har narsaga qodir, kuchli Zotsan, ey Alloh. Xush kelibsiz, Ibn Hanbal, muborak tashrif.", "note": null},
  {"num": 538, "time": "00:40:10,319 --> 00:40:20,579", "arabic": "بَارَكَ اللَّهُ بِكَ يَا أَبَا عَبْدِ اللَّهِ، لَمْ أَكُنْ أَتَوَقَّعُ وُجُودَكَ فِي بَغْدَادَ لِوَلَعِكَ بِالرِّحْلَاتِ وَشَغَفِكَ بِالْأَسْفَارِ طَلَبًا لِلْعِلْمِ وَالْحَدِيثِ", "segs": [{"ar": "بَارَكَ اللَّهُ بِكَ يَا أَبَا عَبْدِ اللَّهِ", "uz": "Alloh senga barakot bersin, Abu Abdulloh"}, {"ar": "لَمْ أَكُنْ أَتَوَقَّعُ وُجُودَكَ فِي بَغْدَادَ", "uz": "Bag'dodda bo'lishingni kutmagan edim"}, {"ar": "لِوَلَعِكَ بِالرِّحْلَاتِ وَشَغَفِكَ بِالْأَسْفَارِ طَلَبًا لِلْعِلْمِ وَالْحَدِيثِ", "uz": "sayohatlarga bo'lgan mehring va ilm hamda hadis izlab safarlarga chanqoqligingdan"}], "full_uz": "Alloh senga barakot bersin, Abu Abdulloh — sayohatlarga bo'lgan mehring va ilm hamda hadis izlab safarlarga chanqoqligingdan, Bag'dodda bo'lishingni kutmagan edim.", "note": null},
  {"num": 540, "time": "00:40:20,579 --> 00:40:29,720", "arabic": "اَلْحَقُّ مَا قُلْتَ يَا شَيْخَنَا، فَقَدْ كُنْتُ أُفَكِّرُ فِي الْخُرُوجِ إِلَى صَنْعَاءَ، وَلَكِنْ حَالَتْ ظُرُوفٌ دُونَ ذَلِكَ", "segs": null, "full_uz": "Aytganingiz to'g'ri, shayximiz — San'oga chiqishni o'ylayotgan edim, ammo sharoitlar buni to'sdi.", "note": null},
  {"num": 542, "time": "00:40:29,720 --> 00:40:37,400", "arabic": "إِلَى أَبِي بَكْرٍ الْحُمَيْدِيِّ عَبْدِ الرَّزَّاقِ بْنِ هَمَّامٍ الصَّنْعَانِيِّ؟ أَجَلْ", "segs": null, "full_uz": "Abu Bakr al-Humaydiy — Abdurazzaq ibn Hammom as-San'oniyga bormoqchimidingiz? Ha.", "note": null},
  {"num": 544, "time": "00:40:37,400 --> 00:40:44,340", "arabic": "وَلَا أَكْتُمُكَ سِرًّا يَا أَبَا عَبْدِ اللَّهِ، قَدْ أَلَمَّ بِيَ الْأَسَى لِعَدَمِ خُرُوجِي إِلَيْهِ", "segs": null, "full_uz": "Sirni yashirmayman, Abu Abdulloh — unga chiqmaganimdan afsuslanardim.", "note": null},
  {"num": 546, "time": "00:40:44,340 --> 00:40:55,120", "arabic": "وَلَكِنْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ، وَقَدْ كَانَ خَيْرًا لِي وَالْحَمْدُ لِلَّهِ أَنْ أَحْظَى بِلِقَائِكَ هُنَا فِي بَغْدَادَ", "segs": [{"ar": "وَلَكِنْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ", "uz": "Ammo — «yoqtirmagan narsangiz siz uchun yaxshiroq bo'lishi mumkin» deganidek"}, {"ar": "وَقَدْ كَانَ خَيْرًا لِي وَالْحَمْدُ لِلَّهِ أَنْ أَحْظَى بِلِقَائِكَ هُنَا فِي بَغْدَادَ", "uz": "bu men uchun yaxshi bo'ldi, alhamdulillah, sizga shu yerda Bag'dodda erishganim uchun"}], "full_uz": "Ammo — «yoqtirmagan narsangiz siz uchun yaxshiroq bo'lishi mumkin» deganidek, bu men uchun yaxshi bo'ldi, alhamdulillah, sizga shu yerda Bag'dodda erishganim uchun.", "note": "«عَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ» — Baqara surasi, 2:216-oyatga ishora."},
  {"num": 548, "time": "00:40:55,119 --> 00:41:05,440", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَحْمَدُ، لَقَدْ خَفَّفَ عَنِّي تَكَلُّفَ السَّفَرِ وَمُفَارَقَةَ الْأَهْلِ أَنِّي أَقْصِدُ بَلَدًا أَنْتُمْ سَاكِنُوهُ", "segs": null, "full_uz": "Alloh senga barakot bersin, Ahmad — sizlar yashaydigan yurtga qarab borayotganim, safar mashaqqati va ahldan ajralish og'irligini menga yengillashtirdi.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}